('248', 'vc_email', 'vc@srku.edu.in'),
('250', 'vc_salutation', 'Dear Students, Scholars, Faculty Colleagues, and Visitors,'),
('253', 'vc_msg3', 'Our 1,000+ distinguished faculty members—including experienced professors, medical surgeons, scientists, and legal scholars—serve not just as teachers, but as dedicated mentors who nurture the unique talents of each individual student. Through continuous faculty development and active research initiatives, we maintain the highest standards of academic delivery.'),
('254', 'vc_msg4', 'To all our learners: SRKU is your canvas. Strive for excellence, question conventional thinking, embrace multidisciplinary perspectives, and lead with empathy. Together, let us contribute meaningfully to the advancement of knowledge, human welfare, and the nation.'),
('255', 'vc_goals', 'Choice Based Credit System (CBCS)\r\nIndustry-Integrated Curriculum & Internships\r\nInterdisciplinary Research Publications\r\nGlobal Academic Partnerships & MOUs'),
