('365', 'facilities_desc', 'Sarvepalli Radhakrishnan University (SRKU) provides world-class infrastructure and holistic amenities designed to enrich student learning, research innovation, physical fitness, and community living.'),
('506', 'chairman_photo', 'assets/uploads/2026/08/dr-sunil-kapoor.jpeg'),
('507', 'why_srku_empower_title', 'Empowering Minds. Inspiring Innovation. Building Future Leaders.'),
('508', 'why_srku_empower_desc', 'At SRK University, education is more than earning a degree—it\'s about developing the knowledge, skills, and confidence to succeed in a rapidly changing world. Our multidisciplinary learning environment combines academic excellence, practical exposure, innovation, and industry engagement to prepare students for meaningful careers and lifelong success.'),
('509', 'why_srku_reason_1_title', 'Multidisciplinary Education'),
('510', 'why_srku_reason_1_desc', 'We offer over 50 diverse programmes spanning Medical, Dental, Nursing, Engineering, Management, Law, Commerce, Agriculture, Science, and Humanities. Students choose courses aligned with their aspirations and the National Education Policy 2020.'),
('511', 'why_srku_reason_2_title', 'State-of-the-Art Infrastructure'),
('512', 'why_srku_reason_2_desc', 'Our lush green campus spans a cosmopolitan setting with modern laboratories, interactive learning spaces, high-tech medical facilities, and libraries equipped with the latest technology and resources.'),
('513', 'why_srku_reason_3_title', 'NAAC-Graded Excellence'),
('514', 'why_srku_reason_3_desc', 'SRK University is NAAC-accredited, ensuring quality education meets international standards. Our commitment to continuous improvement and academic rigor sets us apart from other private universities in Bhopal.'),
('515', 'why_srku_reason_4_title', 'Industry & Research Partnerships'),
('516', 'why_srku_reason_4_desc', 'We foster strong collaborations with leading industries for internships, placements, and research initiatives, ensuring students gain hands-on experience and are job-ready upon graduation.'),
('517', 'why_srku_reason_5_title', 'Diverse Student Community'),
('518', 'why_srku_reason_5_desc', 'Our campus welcomes students from all corners of India, creating a multicultural environment that enriches learning and promotes cross-cultural understanding.'),
('519', 'why_srku_reason_6_title', 'Holistic Student Development'),
('520', 'why_srku_reason_6_desc', 'At SRK University, students grow beyond academics through sports, cultural activities, leadership programmes, innovation, and community engagement, building confidence, teamwork, and essential life skills for future success.'),
('521', 'student_fest_title', 'Tarang — Annual Cultural Fest'),
('522', 'student_fest_desc', 'Three days of star-studded musical concerts, fashion shows, dance competitions, and theatrical performances with 10,000+ attendees.');
