INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `meta_description`, `status`, `created_at`, `banner_title`, `banner_subtitle`, `banner_img`) VALUES
('1', 'Why SRK University', 'why-srk', '<div class=\"why-srk-content\"><h2 class=\"text-maroon fw-bold mb-4\">Why Choose Sarvepalli Radhakrishnan University, Bhopal?</h2><p class=\"lead text-dark\">Sarvepalli Radhakrishnan University (SRKU) is Central India\'s premier academic and research powerhouse, established by Madhya Pradesh Niji Vishwavidyalaya Act and recognized by the University Grants Commission (UGC) under Section 2(f).</p><div class=\"row g-4 my-4\"><div class=\"col-md-6\"><div class=\"p-4 bg-light rounded-4 border-start border-4 border-danger h-100\"><h4 class=\"text-navy fw-bold\"><i class=\"fas fa-microscope text-danger me-2\"></i> 42+ Modern Laboratories</h4><p class=\"text-muted mb-0\">High-end computing labs, pharmaceutical analysis suites, robotic testbeds, agricultural experimental farms, and clinical simulation centers.</p></div></div><div class=\"col-md-6\"><div class=\"p-4 bg-light rounded-4 border-start border-4 border-danger h-100\"><h4 class=\"text-navy fw-bold\"><i class=\"fas fa-briefcase text-danger me-2\"></i> 94% Placement Record</h4><p class=\"text-muted mb-0\">Strong industry linkages with 120+ MNC recruiting partners delivering highest package of 12 LPA and consistent corporate placements.</p></div></div><div class=\"col-md-6\"><div class=\"p-4 bg-light rounded-4 border-start border-4 border-danger h-100\"><h4 class=\"text-navy fw-bold\"><i class=\"fas fa-user-graduate text-danger me-2\"></i> Multi-Disciplinary Ecosystem</h4><p class=\"text-muted mb-0\">Over 90+ degree programs spanning Engineering, Pharmacy, Medicine, Nursing, Management, Law, Agriculture, and Paramedical Sciences.</p></div></div><div class=\"col-md-6\"><div class=\"p-4 bg-light rounded-4 border-start border-4 border-danger h-100\"><h4 class=\"text-navy fw-bold\"><i class=\"fas fa-hospital-user text-danger me-2\"></i> 750+ Bed Teaching Hospital</h4><p class=\"text-muted mb-0\">On-campus super-specialty hospital providing live hands-on clinical exposure for medical, nursing, and paramedical students.</p></div></div></div></div>', 'Why Choose Sarvepalli Radhakrishnan University Bhopal - 42+ Labs, 94% Placement Record, UGC Recognized', 'published', '2026-09-11 17:18:44', 'Why Choose Sarvepalli Radhakrishnan University', 'Academic Excellence, Innovative Research & Industry-Ready Placements', 'assets/uploads/2026/07/001.webp'),
('2', 'Vision & Mission', 'vision-mission', '<div class=\"vision-mission-content\"><div class=\"card p-4 p-md-5 border-0 shadow-sm rounded-4 mb-4 bg-light\"><div class=\"d-flex align-items-center gap-3 mb-3\"><div class=\"bg-danger-subtle text-danger rounded-circle p-3\"><i class=\"fas fa-eye fa-2x\"></i></div><h2 class=\"text-maroon fw-bold mb-0\">Our Vision</h2></div><p class=\"text-dark lead mb-0\">\"To emerge as a premier global university dedicated to value-based technical, medical, and higher education, pioneering groundbreaking research, fostering innovation, and empowering students with ethical leadership to transform society.\"</p></div><div class=\"card p-4 p-md-5 border-0 shadow-sm rounded-4 mb-4 bg-light\"><div class=\"d-flex align-items-center gap-3 mb-3\"><div class=\"bg-danger-subtle text-danger rounded-circle p-3\"><i class=\"fas fa-bullseye fa-2x\"></i></div><h2 class=\"text-navy fw-bold mb-0\">Our Mission</h2></div><ul class=\"list-unstyled d-flex flex-column gap-3 mb-0 text-dark\" style=\"font-size:1.05rem;\"><li><i class=\"fas fa-check-circle text-danger me-2\"></i> <strong>Quality Education:</strong> Imparting experiential and industry-relevant education that nurtures critical thinking, technical proficiency, and creative innovation.</li><li><i class=\"fas fa-check-circle text-danger me-2\"></i> <strong>Research & Development:</strong> Fostering an interdisciplinary research ecosystem to address national and global societal challenges.</li><li><i class=\"fas fa-check-circle text-danger me-2\"></i> <strong>Industry Integration:</strong> Collaborating with leading global corporations and research institutions for curriculum alignment and student career advancement.</li><li><i class=\"fas fa-check-circle text-danger me-2\"></i> <strong>Ethical Character:</strong> Inculcating moral integrity, environmental sustainability, social responsibility, and national values in future leaders.</li></ul></div></div>', 'Vision and Mission of Sarvepalli Radhakrishnan University Bhopal', 'published', '2026-09-11 17:18:44', 'Our Vision & Strategic Mission', 'Pioneering Groundbreaking Research, Experiential Learning & Ethical Leadership', 'assets/uploads/2026/07/002.webp'),
('3', 'Statutory Accreditations & Approvals', 'accreditation', '<div class=\"accreditation-content\"><h2 class=\"text-maroon fw-bold mb-3\">Statutory Approvals & Accreditations</h2><p class=\"lead text-muted mb-4\">Sarvepalli Radhakrishnan University is established by Madhya Pradesh Act No. 17 of 2015 and duly recognized by the University Grants Commission (UGC) under section 2(f) of the UGC Act, 1956.</p></div>', 'Statutory Approvals and Accreditations - UGC, AICTE, PCI, INC, BCI, NMC', 'published', '2026-09-11 17:18:44', 'Accreditation & Statutory Approvals', 'Recognized by UGC, AICTE, PCI, INC, BCI, NMC, DCI & NCISM', 'assets/uploads/2026/07/003.webp'),
('4', 'Board of Management', 'board-of-management', '<div class=\'document-content-summary\'><p>Official documentation outlining the composition and executive powers of the Board of Management, overseeing overall administration, faculty recruitment, infrastructure creation, and operational governance.</p><ul><li>Executive body responsible for administrative operations and management.</li><li>Review and sanction of academic appointments and cadre approvals.</li><li>Establishment of departments, centers, and infrastructure expansion.</li><li>Execution of statutory regulations and ordinances.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Board-of-Management.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official documentation outlining the composition and executive powers of the Board of Management, overseeing overall administration, faculty recruitment, infrastructure creation, and operational governance.', 'published', '2026-09-11 17:18:44', 'Board of Management', 'Executive Governance, Appointments & Administrative Affairs', 'assets/uploads/pdf/Board-of-Management.pdf'),
('5', 'Constituent Units & Colleges', 'constituent-unit', '<div class=\"units-content\"><h2 class=\"text-maroon fw-bold mb-4\">Constituent Colleges & Schools of SRKU</h2><p class=\"lead text-muted mb-4\">The university houses dedicated constituent institutes offering specialized degree and research programs with world-class faculty and facilities.</p></div>', 'Constituent Colleges and Schools of Sarvepalli Radhakrishnan University', 'published', '2026-09-11 17:18:44', 'Constituent Colleges & Schools', '26 Recognized Academic Units Offering 90+ Degree Programmes', 'assets/uploads/2026/07/001.webp'),
('6', 'Admission Guidelines', 'admission', '<div class=\"admission-content\"><h2 class=\"text-maroon fw-bold mb-3\">Admission Guidelines 2026-27</h2><p class=\"lead text-muted mb-4\">Admissions at Sarvepalli Radhakrishnan University are transparent, merit-based, and aligned with statutory regulatory norms.</p></div>', 'SRKU Admission Process, Guidelines and Eligibility 2026-27', 'published', '2026-09-11 17:18:44', 'Admission Guidelines 2026-27', 'Simple, Transparent & Merit-Based Admissions Across All Streams', 'assets/uploads/2026/07/002.webp'),
('7', 'Sports Facilities', 'sports-facilities', '<div class=\'document-content-summary\'><p>Overview of world-class outdoor and indoor sports facilities, athletic tracks, cricket ground, football arena, basketball courts, and fitness centers at SRK University.</p><ul><li>Olympic-standard athletic track and multipurpose sports grounds.</li><li>Dedicated indoor complex for Badminton, Table Tennis, Chess, and Carrom.</li><li>Modern fitness center and gymnasium with certified trainers.</li><li>Annual sports meet, inter-university tournaments, and athletic scholarships.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/sports-Facilities.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Overview of world-class outdoor and indoor sports facilities, athletic tracks, cricket ground, football arena, basketball courts, and fitness centers at SRK University.', 'published', '2026-09-12 10:38:32', 'Sports Facilities', 'Sports Infrastructure, Athletic Complexes & University Gymnasium', 'assets/uploads/2025/10/new-update/sports-Facilities.pdf'),
('8', 'NCC & NSS', 'ncc-nss', '<div class=\'document-content-summary\'><p>Details of active NCC battalions and NSS units at SRKU promoting leadership, community service, discipline, social outreach, and defense career preparedness.</p><ul><li>Authorized NCC Senior Division army wings offering B &amp; C certificates.</li><li>Active NSS volunteer units organizing regular blood donation and rural health camps.</li><li>Special reservation and career advantage for defense forces and public services.</li><li>Participation in Republic Day Parade and National Integration Camps.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/NCC-NSS-Details.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Details of active NCC battalions and NSS units at SRKU promoting leadership, community service, discipline, social outreach, and defense career preparedness.', 'published', '2026-09-12 10:38:32', 'NCC & NSS', 'National Cadet Corps & National Service Scheme Activities & Units', 'assets/uploads/pdf/NCC-NSS-Details.pdf'),
('9', 'Hostel Details', 'hostel-details', '<div class=\'document-content-summary\'><p>Comprehensive documentation of on-campus boys and girls hostels featuring furnished rooms, 24x7 security, dining mess, and resident warden support.</p><ul><li>Separate hostel blocks for boys and girls with 24x7 CCTV and security personnel.</li><li>Nutritious vegetarian and multi-cuisine dining hall supervised by food safety auditors.</li><li>High-speed Wi-Fi connectivity, laundry services, and solar hot water facility.</li><li>Resident wardens, anti-ragging squad coverage, and medical emergency transport.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Hostel-Details.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Comprehensive documentation of on-campus boys and girls hostels featuring furnished rooms, 24x7 security, dining mess, and resident warden support.', 'published', '2026-09-12 10:38:32', 'Hostel Details', 'On-Campus Student Residential Facilities, Dining, Security & Amenities', 'assets/uploads/2025/10/new-update/Hostel-Details.pdf'),
('10', 'Placement Cell', 'placement-cell', '<div class=\'document-content-summary\'><p>Official overview of the University Training &amp; Placement Cell coordinating corporate tie-ups, personality enhancement workshops, mock interviews, internships, and campus recruitment drives.</p><ul><li>120+ leading corporate recruitment partners and Fortune 500 hiring tie-ups.</li><li>Specialized technical aptitude, coding bootcamps, and soft skill grooming.</li><li>Highest package benchmarks, average pay growth, and multi-offer opportunities.</li><li>Dedicated industry internship liaison and summer project mentorship.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/placement-cell.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official overview of the University Training & Placement Cell coordinating corporate tie-ups, personality enhancement workshops, mock interviews, internships, and campus recruitment drives.', 'published', '2026-09-12 10:38:32', 'Placement Cell', 'Corporate Relations, Soft Skill Training, Internships & Campus Recruitment', 'assets/uploads/pdf/placement-cell.pdf'),
('11', 'Student Grievance Redressal Committee', 'student-grievance-committee', '<div class=\'document-content-summary\'><p>Official notification delineating the constitution, membership, powers, and procedure of the Student Grievance Redressal Committee (SGRC) constituted in compliance with UGC Regulations.</p><ul><li>Independent committee headed by senior faculty to resolve student complaints.</li><li>Time-bound 15-day grievance investigation and redressal mechanism.</li><li>Special provisions for online registration of academic and hostel concerns.</li><li>Direct appellate pathway to University Ombudsman.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/allCommittee/Student_Grievance_Committee.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official notification delineating the constitution, membership, powers, and procedure of the Student Grievance Redressal Committee (SGRC) constituted in compliance with UGC Regulations.', 'published', '2026-09-12 10:38:32', 'Student Grievance Redressal Committee', 'Institutional Grievance Redressal Committee (SGRC) & Regulations', 'assets/uploads/2025/allCommittee/Student_Grievance_Committee.pdf'),
('12', 'University Ombudsman', 'ombudsman', '<div class=\'document-content-summary\'><p>Official appointment, jurisdiction, and contact details of the University Ombudsman appointed in accordance with UGC grievance redressal regulations for independent adjudication.</p><ul><li>Statutory independent appellate authority for aggrieved university students.</li><li>Senior Academician / Former District Judge appointed under UGC regulations.</li><li>Impartial hearing and binding recommendations on contested grievances.</li><li>Guaranteed protection against victimization or unfair treatment.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/ombudsman.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official appointment, jurisdiction, and contact details of the University Ombudsman appointed in accordance with UGC grievance redressal regulations for independent adjudication.', 'published', '2026-09-12 10:38:32', 'University Ombudsman', 'Statutory University Ombudsman for Student Grievance Adjudication', 'assets/uploads/pdf/ombudsman.pdf'),
('13', 'Health Facility', 'health-facility', '<div class=\'document-content-summary\'><p>Comprehensive overview of on-campus health facilities, round-the-clock emergency medical care, qualified medical officers, pharmacy, ambulances, and association with 750+ bed teaching hospital.</p><ul><li>Immediate on-campus primary care center with resident medical officers and nurses.</li><li>Direct linkage with SRK University 750+ Bed Super-Specialty Teaching Hospital.</li><li>24x7 emergency response with dedicated ambulances on standby.</li><li>Annual health checkups, vaccination drives, and student wellness support.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Health facility.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Comprehensive overview of on-campus health facilities, round-the-clock emergency medical care, qualified medical officers, pharmacy, ambulances, and association with 750+ bed teaching hospital.', 'published', '2026-09-12 10:38:32', 'Health Facility', '24x7 Campus Medical Care, On-Site Hospital & Emergency Services', 'assets/uploads/pdf/Health-facility.pdf'),
('14', 'Internal Complaint Committee (ICC)', 'internal-complaint-committee', '<div class=\'document-content-summary\'><p>Official constitution, mandate, and contact details of the Internal Complaint Committee established in compliance with POSH Act regulations to ensure a secure, respectful, and gender-inclusive campus environment.</p><ul><li>Prevention, prohibition, and redressal of sexual harassment and discrimination.</li><li>Confidential and time-bound inquiry mechanism for registered grievances.</li><li>Regular gender-sensitization workshops, awareness drives, and counseling support.</li><li>Zero tolerance towards harassment across campus facilities and hostels.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Internal-Complaint-Committee.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official constitution, mandate, and contact details of the Internal Complaint Committee established in compliance with POSH Act regulations to ensure a secure, respectful, and gender-inclusive campus environment.', 'published', '2026-09-12 10:38:32', 'Internal Complaint Committee (ICC)', 'Grievance Redressal, Gender Sensitization & Women Safety at Workplace', 'assets/uploads/pdf/Internal-Complaint-Committee.pdf'),
('15', 'Anti-Ragging Committee & Squad', 'anti-ragging', '<div class=\'document-content-summary\'><p>University notification on Anti-Ragging Committee and Squads constituted as per Supreme Court directives and UGC Anti-Ragging regulations, maintaining a 100% ragging-free campus.</p><ul><li>Zero tolerance policy with immediate punitive consequences for ragging.</li><li>24x7 monitoring squads across academic zones, dining halls, and student hostels.</li><li>National Anti-Ragging helpline coordinates and institutional nodal officers.</li><li>Mandatory affidavits collected from students and parents at admission.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/allCommittee/AntiRagging.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'University notification on Anti-Ragging Committee and Squads constituted as per Supreme Court directives and UGC Anti-Ragging regulations, maintaining a 100% ragging-free campus.', 'published', '2026-09-12 10:38:32', 'Anti-Ragging Committee & Squad', 'Zero Tolerance Policy, Anti-Ragging Squad & Student Welfare Mandate', 'assets/uploads/2025/allCommittee/AntiRagging.pdf'),
('16', 'Equal Opportunity Cell', 'equal-opportunity-cell', '<div class=\'document-content-summary\'><p>Official notification and operational charter of the Equal Opportunity Cell fostering an inclusive, equitable, and barrier-free educational environment for students of all backgrounds.</p><ul><li>Holistic support for differently-abled and economically marginalized scholars.</li><li>Ensuring barrier-free infrastructure, ramps, accessible elevators, and tactile paths.</li><li>Skill-enhancement workshops, digital accessibility tools, and assistive tech.</li><li>Sensitization programs on inclusivity, mutual respect, and social equity.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/allCommittee/EqualOppurtunityCell.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official notification and operational charter of the Equal Opportunity Cell fostering an inclusive, equitable, and barrier-free educational environment for students of all backgrounds.', 'published', '2026-09-12 10:38:32', 'Equal Opportunity Cell', 'Inclusive Campus Environment, Accessibility & Student Support', 'assets/uploads/pdf/EqualOppurtunityCell.pdf'),
('17', 'Socio Economically Disadvantaged Groups Cell (SEDG)', 'sedg-cell', '<div class=\'document-content-summary\'><p>Institutional framework of the SEDG Cell constituted in alignment with National Education Policy (NEP 2020) and UGC guidelines to empower socio-economically disadvantaged students.</p><ul><li>Institutionalized financial guidance, scholarship assistance, and fee concessions.</li><li>Academic bridge courses, language development, and remedial mentoring.</li><li>Psychosocial counseling and peer support networks.</li><li>Special placement preparation and corporate sponsorship linkage.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Socio-Economically-Disadvantaged-Groups-Cell-(SEDG).pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Institutional framework of the SEDG Cell constituted in alignment with National Education Policy (NEP 2020) and UGC guidelines to empower socio-economically disadvantaged students.', 'published', '2026-09-12 10:38:32', 'Socio Economically Disadvantaged Groups Cell (SEDG)', 'UGC NEP-2020 Aligned SEDG Cell for Equity & Holistic Support', 'assets/uploads/pdf/Socio-Economically-Disadvantaged-Groups-Cell-(SEDG).pdf'),
('18', 'Facilities For Differently Abled Students', 'differently-abled-facilities', '<div class=\'document-content-summary\'><p>Documentation of barrier-free campus infrastructure including wheelchair ramps, accessible elevators, tactile pathways, designated washrooms, and assistive software tools for differently-abled students.</p><ul><li>Barrier-free architectural design with wheelchair ramps and handrails across all blocks.</li><li>Elevators equipped with Braille keypads and voice announcements.</li><li>Specially designed, barrier-free accessible washrooms on all academic floors.</li><li>Assistive reading software, screen readers, and dedicated library seating.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/FACILITIES FORDIFFERENTLYABLED STUDENTS.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Documentation of barrier-free campus infrastructure including wheelchair ramps, accessible elevators, tactile pathways, designated washrooms, and assistive software tools for differently-abled students.', 'published', '2026-09-12 10:38:32', 'Facilities For Differently Abled Students', 'Barrier-Free Built Environment, Assistive Infrastructure & Ramps', 'assets/uploads/pdf/FACILITIES-FORDIFFERENTLYABLED-STUDENTS.pdf'),
('19', 'About Sarvepalli Radhakrishnan University', 'about-us', '<div class=\'document-content-summary\'><p>Comprehensive institutional overview of Sarvepalli Radhakrishnan University (SRKU), Bhopal highlighting university milestones, leadership, campus infrastructure, academic faculties, research output, and state-of-the-art facilities.</p><ul><li>Recognized under Section 2(f) of the UGC Act 1956 &amp; MP Niji Vishwavidyalaya Adhiniyam.</li><li>Multidisciplinary campus spread across 85+ lush green acres in Bhopal.</li><li>Constituent colleges in Engineering, Medicine, Dental, Pharmacy, Nursing, Law, and Management.</li><li>Modern research laboratories, central digital library, and 750+ bed teaching hospital.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/about-us.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Comprehensive institutional overview of Sarvepalli Radhakrishnan University (SRKU), Bhopal highlighting university milestones, leadership, campus infrastructure, academic faculties, research output, and state-of-the-art facilities.', 'published', '2026-09-12 11:02:16', 'About Sarvepalli Radhakrishnan University', 'Institutional Profile, Heritage, Vision & Multidisciplinary Infrastructure', 'assets/uploads/2025/10/new-update/about-us.pdf'),
('20', 'Act & Statutes', 'act-statutes', '<div class=\'document-content-summary\'><p>Official legislative act enacted by the Madhya Pradesh State Legislature and gazetted statutes governing the establishment, statutory powers, governance bodies, and operational framework of Sarvepalli Radhakrishnan University.</p><ul><li>Statutory enactment under MP Niji Vishwavidyalaya Adhiniyam.</li><li>Official Madhya Pradesh Government Gazette notifications.</li><li>Powers, duties, and jurisdiction of statutory university authorities.</li><li>Legal and administrative framework for academic degree conferment.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Act-Statutes.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official legislative act enacted by the Madhya Pradesh State Legislature and gazetted statutes governing the establishment, statutory powers, governance bodies, and operational framework of Sarvepalli Radhakrishnan University.', 'published', '2026-09-12 11:02:16', 'Act & Statutes', 'State Legislative Act, Gazette Notifications & University Statutes', 'assets/uploads/2025/10/new-update/Act-Statutes.pdf'),
('21', 'Institutional Development Plan (IDP)', 'institutional-development-plan', '<div class=\'document-content-summary\'><p>Comprehensive strategic institutional development plan formulated in alignment with NEP 2020 guidelines, charting multi-year goals for curriculum modernization, research innovation, global faculty recruitment, and student empowerment.</p><ul><li>Multi-year strategic roadmap aligned with NEP 2020 directives.</li><li>Infrastructure development, smart classrooms, and central instrumentation labs.</li><li>Faculty development programs and industry-aligned skill centers.</li><li>Metrics for research funding, patent generation, and student placements.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Institutional-Development-Plan.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Comprehensive strategic institutional development plan formulated in alignment with NEP 2020 guidelines, charting multi-year goals for curriculum modernization, research innovation, global faculty recruitment, and student empowerment.', 'published', '2026-09-12 11:02:16', 'Institutional Development Plan (IDP)', 'Strategic Roadmap for Academic Excellence, NEP 2020 & Infrastructure Augmentation', 'assets/uploads/2025/10/new-update/Institutional-Development-Plan.pdf'),
('22', 'Constituent Units of SRK University', 'constituent-units', '<div class=\'document-content-summary\'><p>Official directory of constituent units, institutes, and departments operating under the statutory umbrella of Sarvepalli Radhakrishnan University Bhopal, approved by respective national regulatory councils.</p><ul><li>Complete list of constituent colleges across Medical, Dental, Pharmacy, Engineering, and Law.</li><li>Regulatory council approval references (NMC, DCI, PCI, AICTE, BCI, INC).</li><li>Campus locations, academic programs, and sanctioned student intake.</li><li>Interdisciplinary academic resources and shared hospital infrastructure.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Constituent-units.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official directory of constituent units, institutes, and departments operating under the statutory umbrella of Sarvepalli Radhakrishnan University Bhopal, approved by respective national regulatory councils.', 'published', '2026-09-12 11:02:16', 'Constituent Units of SRK University', 'Approved Constituent Colleges, Specialized Institutes & Faculties', 'assets/uploads/2025/10/new-update/Constituent-units.pdf'),
('23', 'Accreditation & Institutional Ranking', 'accreditation-ranking', '<div class=\'document-content-summary\'><p>Official record of accreditations, certifications, and institutional rankings conferred on Sarvepalli Radhakrishnan University by apex educational and professional bodies.</p><ul><li>UGC Section 2(f) statutory recognition.</li><li>National Institutional Ranking Framework (NIRF) participation and disclosures.</li><li>Professional council certifications across technical and medical faculties.</li><li>Quality benchmarks validated by internal and external academic audits.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Accreditation-Ranking.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official record of accreditations, certifications, and institutional rankings conferred on Sarvepalli Radhakrishnan University by apex educational and professional bodies.', 'published', '2026-09-12 11:02:16', 'Accreditation & Institutional Ranking', 'National Accreditations, Regulatory Approvals & Institutional Rankings', 'assets/uploads/pdf/Accreditation-Ranking.pdf'),
('24', 'Recognition & Statutory Approvals', 'recognition-approval', '<div class=\'document-content-summary\'><p>Gazetted statutory recognitions, UGC notifications, and apex regulatory council approval orders authorising degree conferral and academic operations at SRKU.</p><ul><li>Statutory approvals from UGC, AICTE, NMC, PCI, BCI, and INC.</li><li>State Government authorization orders and gazetted regulations.</li><li>Validations for Undergraduate, Postgraduate, and Doctoral degree offerings.</li><li>Periodic extension of approval (EOA) notifications.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Recognition-Approval.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Gazetted statutory recognitions, UGC notifications, and apex regulatory council approval orders authorising degree conferral and academic operations at SRKU.', 'published', '2026-09-12 11:02:16', 'Recognition & Statutory Approvals', 'UGC, AICTE, PCI, INC, BCI, AYUSH & Statutory Council Approvals', 'assets/uploads/2025/10/new-update/Recognition-Approval.pdf'),
('25', 'Annual Report 2024-25', 'annual-report', '<div class=\'document-content-summary\'><p>Comprehensive annual report of Sarvepalli Radhakrishnan University detailing annual academic performance, research publications, faculty achievements, admissions, and campus developments.</p><ul><li>Summary of academic milestones achieved during the academic year 2024-25.</li><li>Student enrollment, examination results, and convocation degree statistics.</li><li>Research grants, funded projects, patents, and peer-reviewed publications.</li><li>Campus placements, recruitment partners, and student achievement honors.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Recognition-Approval.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Comprehensive annual report of Sarvepalli Radhakrishnan University detailing annual academic performance, research publications, faculty achievements, admissions, and campus developments.', 'published', '2026-09-12 11:02:16', 'Annual Report 2024-25', 'Annual Institutional Progress, Academic Achievements & Financial Summary', 'assets/uploads/2025/10/new-update/Recognition-Approval.pdf'),
('26', 'Details of Sponsoring Body', 'details-of-sponsoring-body', '<div class=\'document-content-summary\'><p>Official registration documentation, charter, objectives, and governing body details of the RKDF Education Society, the sponsoring body of Sarvepalli Radhakrishnan University Bhopal.</p><ul><li>Registration under the Societies Registration Act.</li><li>Visionary educational leadership steering 25+ institutions across Central India.</li><li>Philanthropic initiatives, scholarship endowments, and rural healthcare delivery.</li><li>Statutory compliance documents and financial transparency records.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Details_of_Sponsoring_Body.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official registration documentation, charter, objectives, and governing body details of the RKDF Education Society, the sponsoring body of Sarvepalli Radhakrishnan University Bhopal.', 'published', '2026-09-12 11:02:16', 'Details of Sponsoring Body', 'RKDF Education Society - Founding Trust, Objectives & Governance', 'assets/uploads/2025/10/new-update/Details_of_Sponsoring_Body.pdf'),
('27', 'Council of Technical Education (EOA Report)', 'council-of-technical-education', '<div class=\'document-content-summary\'><p>Official AICTE Extension of Approval (EOA) letters specifying approved technical, engineering, pharmacy, and management courses, along with sanctioned intakes and institutional norms.</p><ul><li>AICTE extension of approval for B.Tech, M.Tech, MBA, and MCA programmes.</li><li>Sanctioned student intake capacity per academic discipline.</li><li>Faculty cadre compliance and lab infrastructure audit records.</li><li>Adherence to AICTE approval process handbook guidelines.</li></ul><p><a href=\'http://localhost/assets/uploads/2023/09/EOA_Report_2020-21-1.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official AICTE Extension of Approval (EOA) letters specifying approved technical, engineering, pharmacy, and management courses, along with sanctioned intakes and institutional norms.', 'published', '2026-09-12 11:02:16', 'Council of Technical Education (EOA Report)', 'AICTE Extension of Approval (EOA) Compliance & Sanctioned Intakes', 'assets/uploads/2023/09/EOA_Report_2020-21-1.pdf'),
('28', 'University Ordinance (1 to 92)', 'university-ordinance', '<div class=\'document-content-summary\'><p>Official gazetted university ordinances (Ordinance 1 to 92) governing course admission criteria, examination grading schemas, conduct of examinations, fee structure, and degree conferral.</p><ul><li>Detailed course-by-course ordinances for Undergraduate and Postgraduate programs.</li><li>Examination passing standards, grace marks regulations, and grade conversions.</li><li>Rules for condonation of attendance, migration, and revaluation.</li><li>Disciplinary regulations and code of student conduct.</li></ul><p><a href=\'http://localhost/assets/uploads/2023/09/university-ordinance.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official gazetted university ordinances (Ordinance 1 to 92) governing course admission criteria, examination grading schemas, conduct of examinations, fee structure, and degree conferral.', 'published', '2026-09-12 11:02:16', 'University Ordinance (1 to 92)', 'Statutory Academic Ordinances, Rules of Admission & Course Syllabi', 'assets/uploads/2026/07/university-ordinance.pdf'),
('29', 'Subsequent Ordinance (93 to 100)', 'ordinance-93-100', '<div class=\'document-content-summary\'><p>Subsequent official university ordinances (Ordinance 93 to 100) notified in the Madhya Pradesh Gazette covering specialized postgraduate curricula, super-specialty medical, paramedical, and research degrees.</p><ul><li>Gazette notifications for newly introduced interdisciplinary courses.</li><li>Regulations for specialized healthcare and technical programs.</li><li>Credit accumulation and transfer framework aligned with NEP 2020.</li><li>Evaluation modalities for advanced certifications and fellowships.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/08/ordinance/ordinance-93-100.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Subsequent official university ordinances (Ordinance 93 to 100) notified in the Madhya Pradesh Gazette covering specialized postgraduate curricula, super-specialty medical, paramedical, and research degrees.', 'published', '2026-09-12 11:02:16', 'Subsequent Ordinance (93 to 100)', 'Gazette Notifications for Specialized Academic Ordinances 93-100', 'assets/uploads/2025/08/ordinance/ordinance-93-100.pdf'),
('30', 'UGC Information (Annexure I)', 'ugc-information', '<div class=\'document-content-summary\'><p>Official statutory disclosure and information submission provided to the University Grants Commission (UGC) pursuant to Section 2(f) requirements, covering campus land, buildings, faculty, and academic programs.</p><ul><li>Full compliance proforma submitted to UGC Expert Committee.</li><li>Physical infrastructure, built-up area, and equipment inventories.</li><li>Faculty rosters, pay scales, and qualification validations.</li><li>Financial stability certificates and endowment fund disclosures.</li></ul><p><a href=\'http://localhost/assets/uploads/2023/05/annexure-I-UGCinfo.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official statutory disclosure and information submission provided to the University Grants Commission (UGC) pursuant to Section 2(f) requirements, covering campus land, buildings, faculty, and academic programs.', 'published', '2026-09-12 11:02:16', 'UGC Information (Annexure I)', 'Statutory Compliance Submission to University Grants Commission (UGC)', 'assets/uploads/2023/05/annexure-I-UGCinfo.pdf'),
('31', 'OBC & Minority Grievance Committee', 'obc-minority', '<div class=\'document-content-summary\'><p>Institutional cell constituted to oversee welfare, redress grievances, and provide academic support to Other Backward Classes (OBC) and Religious/Linguistic Minority students.</p><ul><li>Assistance with state and central scholarship applications (Post-Matric, Merit-cum-Means).</li><li>Remedial coaching and communication skill development workshops.</li><li>Confidential hearing and prompt resolution of academic and social issues.</li><li>Representation in university student welfare councils.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/allCommittee/OBC-Minority.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Institutional cell constituted to oversee welfare, redress grievances, and provide academic support to Other Backward Classes (OBC) and Religious/Linguistic Minority students.', 'published', '2026-09-12 11:02:16', 'OBC & Minority Grievance Committee', 'Welfare, Equal Opportunity & Support for OBC & Minority Students', 'assets/uploads/pdf/OBC-Minority.pdf'),
('32', 'Women Grievance Committee', 'women-grievance-committee', '<div class=\'document-content-summary\'><p>Statutory committee dedicated to ensuring the safety, dignity, and empowerment of female students, faculty, and administrative staff across university campuses.</p><ul><li>Strict adherence to POSH guidelines and UGC gender sensitization mandates.</li><li>Confidential grievance reporting and fast-track investigation hearings.</li><li>Regular counseling sessions, self-defense workshops, and awareness rallies.</li><li>Safe campus corridors, secure hostel accommodation, and women helpline access.</li></ul><p><a href=\'http://localhost/assets/uploads/2024/07/women-grievance-committee.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Statutory committee dedicated to ensuring the safety, dignity, and empowerment of female students, faculty, and administrative staff across university campuses.', 'published', '2026-09-12 11:02:16', 'Women Grievance Committee', 'Women Empowerment, Safety & Internal Complaint Redressal', 'assets/uploads/2024/07/women-grievance-committee.pdf'),
('33', 'SC & ST Grievance Committee', 'sc-st-grievance-committee', '<div class=\'document-content-summary\'><p>Statutory committee established to prevent discrimination, ensure social justice, and promote the academic and professional development of Scheduled Caste (SC) and Scheduled Tribe (ST) students.</p><ul><li>Strict enforcement of Scheduled Castes and the Scheduled Tribes (Prevention of Atrocities) Act.</li><li>Special guidance for government freeship, fellowship, and scholarship schemes.</li><li>Academic mentoring, book bank access, and competitive examination preparation.</li><li>Dedicated nodal officer for transparent dispute resolution.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/allCommittee/SC_ST_Grievance_committee.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Statutory committee established to prevent discrimination, ensure social justice, and promote the academic and professional development of Scheduled Caste (SC) and Scheduled Tribe (ST) students.', 'published', '2026-09-12 11:02:16', 'SC & ST Grievance Committee', 'Prevention of Caste Discrimination & SC/ST Cell Oversight', 'assets/uploads/2025/allCommittee/SC_ST_Grievance_committee.pdf'),
('34', 'Officers of the University', 'officers-of-university', '<div class=\'document-content-summary\'><p>Official gazetted directory of statutory officers of Sarvepalli Radhakrishnan University including the Chancellor, Vice-Chancellor, Registrar, Chief Finance Officer, Deans, and Examination Controller.</p><ul><li>Statutory administrative framework and executive hierarchy.</li><li>Profiles and designations of apex university officers.</li><li>Official contact channels and administrative responsibilities.</li><li>Compliance with State University Act and Ordinances.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/OfficersofUniversity.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official gazetted directory of statutory officers of Sarvepalli Radhakrishnan University including the Chancellor, Vice-Chancellor, Registrar, Chief Finance Officer, Deans, and Examination Controller.', 'published', '2026-09-12 11:02:16', 'Officers of the University', 'Statutory Officers, Leadership & Administrative Authorities', 'assets/uploads/2026/07/OfficersofUniversity.pdf'),
('35', 'Governing Body', 'governing-body', '<div class=\'document-content-summary\'><p>Official constitution and list of distinguished members constituting the Governing Body of Sarvepalli Radhakrishnan University, responsible for strategic policy formulation and institutional stewardship.</p><ul><li>Apex decision-making authority of the University.</li><li>Distinguished academicians, administrators, and industry experts.</li><li>Approval of university budgets, development plans, and expansions.</li><li>Institutional vision and academic governance.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Governing Body.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official constitution and list of distinguished members constituting the Governing Body of Sarvepalli Radhakrishnan University, responsible for strategic policy formulation and institutional stewardship.', 'published', '2026-09-12 11:02:16', 'Governing Body', 'Constitution, Apex Governance & Members of University Governing Body', 'assets/uploads/pdf/Governing-Body.pdf'),
('36', 'Finance Committee', 'finance-committee', '<div class=\'document-content-summary\'><p>Constitution and membership of the University Finance Committee, entrusted with annual financial planning, budget allocations, expenditure monitoring, and internal financial audits.</p><ul><li>Scrutiny of annual budget estimates and capital allocations.</li><li>Monitoring of institutional financial health, grants, and audit reports.</li><li>Resource allocation for laboratory modernization and research seed grants.</li><li>Compliance with statutory accounting and financial norms.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Finance-Committee.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Constitution and membership of the University Finance Committee, entrusted with annual financial planning, budget allocations, expenditure monitoring, and internal financial audits.', 'published', '2026-09-12 11:02:16', 'Finance Committee', 'Financial Oversight, Annual Budgeting & Audit Control', 'assets/uploads/pdf/Finance-Committee.pdf'),
('37', 'Academic Council', 'academic-councils', '<div class=\'document-content-summary\'><p>Official listing of members constituting the Academic Council of SRKU, responsible for maintaining high academic standards, curriculum revisions, pedagogical innovations, and examination regulations.</p><ul><li>Formulation and approval of academic regulations and degree schemes.</li><li>Curriculum development in alignment with NEP 2020 guidelines.</li><li>Approval of new faculties, courses, and interdisciplinary programmes.</li><li>Evaluation standards, credit frameworks, and grading systems.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/ACADEMIC-COUNCIL-20.pdf.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official listing of members constituting the Academic Council of SRKU, responsible for maintaining high academic standards, curriculum revisions, pedagogical innovations, and examination regulations.', 'published', '2026-09-12 11:02:16', 'Academic Council', 'Apex Academic Authority, Curriculum Standards & Examination Framework', 'assets/uploads/pdf/ACADEMIC-COUNCIL-20.pdf.pdf'),
('38', 'Board of Studies', 'board-of-studies', '<div class=\'document-content-summary\'><p>Department-wise committees of the Board of Studies (BOS) comprising subject experts and senior faculty responsible for designing, updating, and evaluating course curricula across disciplines.</p><ul><li>Periodic syllabus revision aligned with emerging industrial requirements.</li><li>Design of practical experiments, project modules, and internship structures.</li><li>Prescription of textbook references, e-learning resources, and research papers.</li><li>Continuous evaluation schemes and question paper frameworks.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/BoardofStudies.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Department-wise committees of the Board of Studies (BOS) comprising subject experts and senior faculty responsible for designing, updating, and evaluating course curricula across disciplines.', 'published', '2026-09-12 11:02:16', 'Board of Studies', 'Departmental Academic Panels, Course Syllabus & Curriculum Panels', 'assets/uploads/pdf/BoardofStudies.pdf'),
('39', 'Academic Leadership', 'academic-leadership', '<div class=\'document-content-summary\'><p>Official directory of Deans, Directors, and Principals steering academic excellence across Engineering, Medical, Dental, Pharmacy, Nursing, Law, Agriculture, Management, and Science faculties.</p><ul><li>Leadership profiles of constituent college heads and faculty deans.</li><li>Directorial oversight of research centers, hospital administration, and labs.</li><li>Industry collaboration, corporate liaison, and global partnerships.</li><li>Mentorship of doctoral research scholars and faculty development.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/AcademicLeadership.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official directory of Deans, Directors, and Principals steering academic excellence across Engineering, Medical, Dental, Pharmacy, Nursing, Law, Agriculture, Management, and Science faculties.', 'published', '2026-09-12 11:02:16', 'Academic Leadership', 'Deans of Faculties, Institute Principals & Departmental Heads', 'assets/uploads/pdf/AcademicLeadership.pdf'),
('40', 'BJMC Syllabus & Scheme', 'bjmc-syllabus-scheme', '<div class=\'document-content-summary\'><p>Comprehensive academic syllabus, semester-wise scheme of examination, subject codes, and practical laboratory components for the Bachelor of Journalism and Mass Communication (BJMC) degree program.</p><ul><li>Semester-wise breakdown of print, television, digital, and radio journalism modules.</li><li>Media law, ethics, public relations, advertising, and corporate communications.</li><li>Practical news anchoring, audio-video production, editing software, and photojournalism.</li><li>Mandatory newsroom internships, media project portfolios, and dissertation guidelines.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Srk-University-BJMC-syllabus-scheme.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Comprehensive academic syllabus, semester-wise scheme of examination, subject codes, and practical laboratory components for the Bachelor of Journalism and Mass Communication (BJMC) degree program.', 'published', '2026-09-12 11:02:16', 'BJMC Syllabus & Scheme', 'Bachelor of Journalism & Mass Communication Curriculum & Evaluation Scheme', 'assets/uploads/pdf/Srk-University-BJMC-syllabus-scheme.pdf'),
('41', 'Details of Academic Programmes', 'details-of-academic-programmes', '<div class=\'document-content-summary\'><p>Comprehensive academic programme directory detailing course nomenclature, duration, intake capacity, and eligibility parameters across faculties.</p><ul><li>90+ programs across Engineering, Medicine, Dental, Pharmacy, Law, and Sciences.</li><li>Sanctioned seat matrices and regulatory approval references.</li><li>NEP-2020 aligned multiple entry-exit credit structures.</li><li>Admission criteria, minimum eligibility percentages, and entrance requisites.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Details-of-Academic-Programmes.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Comprehensive academic programme directory detailing course nomenclature, duration, intake capacity, and eligibility parameters across faculties.', 'published', '2026-09-12 11:02:16', 'Details of Academic Programmes', 'Undergraduate, Postgraduate, Diploma & Doctoral Programmes Directory', 'assets/uploads/pdf/Details-of-Academic-Programmes.pdf'),
('42', 'Academic Calendar 2024-25', 'academic-calendar', '<div class=\'document-content-summary\'><p>Official university academic calendar for odd and even semesters specifying commencement of classes, continuous internal assessments, practical exams, term-end examinations, and vacation schedules.</p><ul><li>Prescribed 90 teaching days per semester standard compliant with UGC norms.</li><li>Schedule for internal assessment tests (MST-I, MST-II), quizzes, and assignments.</li><li>Winter/Summer semester break timelines and gazetted university holidays.</li><li>Terminal university examination and result declaration deadlines.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Academic-Calendar.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official university academic calendar for odd and even semesters specifying commencement of classes, continuous internal assessments, practical exams, term-end examinations, and vacation schedules.', 'published', '2026-09-12 11:02:16', 'Academic Calendar 2024-25', 'Semester Schedule, Teaching Days, Mid-Terms, Breaks & Terminal Examinations', 'assets/uploads/pdf/Academic-Calendar.pdf'),
('43', 'Statutes & Ordinances Pertaining to Academics & Examination', 'statutes-ordinances-academics-examination', '<div class=\'document-content-summary\'><p>Official university statutes and ordinances regulating academic curricula, grading systems, continuous evaluation, and terminal examination protocols.</p><ul><li>Choice Based Credit System (CBCS) rules, credit definitions, and grade point averages (SGPA/CGPA).</li><li>Conduct of practical, viva-voce, theory examinations, and appointment of external examiners.</li><li>Provisions regarding scrutiny, re-totaling, revaluation, and unfair means committee.</li><li>Norms for promotion from one academic semester to the subsequent year.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/statutes-ordinances-pertaining-to-academics-examination.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official university statutes and ordinances regulating academic curricula, grading systems, continuous evaluation, and terminal examination protocols.', 'published', '2026-09-12 11:02:16', 'Statutes & Ordinances Pertaining to Academics & Examination', 'Academic Framework, Evaluation Standards, Grading & Conduct of Examinations', 'assets/uploads/2026/07/statutes-ordinances-pertaining-to-academics-examination.pdf'),
('44', 'School / Department / Centres Directory', 'school-department-centres', '<div class=\'document-content-summary\'><p>Institutional directory listing all university academic schools, teaching departments, specialized clinical centers, and interdisciplinary research facilities under SRKU.</p><ul><li>Complete directory of constituent academic schools and departments.</li><li>Specialized clinical and technical centers supporting high-level studies.</li><li>Interdisciplinary learning hubs, design studios, and simulation labs.</li><li>Departmental leadership contacts and administrative infrastructure.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Constituent-units&Department.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Institutional directory listing all university academic schools, teaching departments, specialized clinical centers, and interdisciplinary research facilities under SRKU.', 'published', '2026-09-12 11:02:16', 'School / Department / Centres Directory', 'Constituent Units, Academic Faculties, Departments & Specialist Research Centres', 'assets/uploads/2025/10/new-update/Constituent-units&Department.pdf'),
('45', 'Faculty & Staff Details', 'faculty-staff-details', '<div class=\'document-content-summary\'><p>Official department-wise directory showcasing distinguished faculty members, academic designations, doctoral qualifications, specializations, and years of teaching/research experience.</p><ul><li>Full faculty roster across 25+ constituent colleges and faculties.</li><li>Professors, Associate Professors, and Assistant Professors with Ph.D. qualifications.</li><li>Research interest domains, patent holders, and funded project investigators.</li><li>Staff-to-student ratios compliant with statutory council standards.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/department-wise-faculty-details.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official department-wise directory showcasing distinguished faculty members, academic designations, doctoral qualifications, specializations, and years of teaching/research experience.', 'published', '2026-09-12 11:02:16', 'Faculty & Staff Details', 'Department-Wise Directory of Professors, Associate Professors & Academic Staff', 'assets/uploads/pdf/department-wise-faculty-details.pdf'),
('46', 'Internal Quality Assurance Cell (IQAC)', 'iqac', '<div class=\'document-content-summary\'><p>Constitution, objectives, quality initiatives, and annual audit procedures of the University Internal Quality Assurance Cell (IQAC) dedicated to continuous institutional quality enhancement.</p><ul><li>Monitoring institutional teaching-learning methodologies and outcome benchmarks.</li><li>Conduction of periodic internal and external academic and administrative audits.</li><li>Stakeholder feedback mechanism from students, alumni, parents, and recruiters.</li><li>Facilitation of faculty development, curriculum revamps, and NAAC/NIRF metrics.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/IQAC.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Constitution, objectives, quality initiatives, and annual audit procedures of the University Internal Quality Assurance Cell (IQAC) dedicated to continuous institutional quality enhancement.', 'published', '2026-09-12 11:02:16', 'Internal Quality Assurance Cell (IQAC)', 'Quality Enhancement Initiatives, Academic Audits & Compliance Framework', 'assets/uploads/pdf/IQAC.pdf'),
('47', 'University Central Library', 'university-library', '<div class=\'document-content-summary\'><p>Detailed information regarding the University Central Library and constituent branch libraries housing over 1,00,000+ volumes, international journals, digital databases, and DELNET subscriptions.</p><ul><li>Extensive repository of textbooks, reference manuals, theses, and rare manuscripts.</li><li>24x7 Digital Library portal with remote access to IEEE, ScienceDirect, PubMed, and DELNET.</li><li>Air-conditioned reading halls accommodating 500+ students simultaneously.</li><li>Automated library management system with RFID barcoding and automated issue/return.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/UniversityLibrary.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Detailed information regarding the University Central Library and constituent branch libraries housing over 1,00,000+ volumes, international journals, digital databases, and DELNET subscriptions.', 'published', '2026-09-12 11:02:16', 'University Central Library', 'Central Knowledge Resource, E-Journals, Digital Library & Learning Spaces', 'assets/uploads/pdf/UniversityLibrary.pdf'),
('48', 'University Prospectus', 'prospectus', '<div class=\'document-content-summary\'><p>Official university prospectus containing detailed information regarding academic departments, undergraduate, postgraduate and doctoral programmes, campus facilities, faculty profiles, and student amenities.</p><ul><li>Overview of 25+ Constituent Colleges, Institutes and University Faculties.</li><li>Undergraduate, Postgraduate, Diploma and Doctoral degree offerings.</li><li>Modern laboratory infrastructure, Central Computing Facility and 750+ Bed Teaching Hospital.</li><li>Scholarships, campus placement records, and student development initiatives.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Prospectus.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official university prospectus containing detailed information regarding academic departments, undergraduate, postgraduate and doctoral programmes, campus facilities, faculty profiles, and student amenities.', 'published', '2026-09-12 11:02:16', 'University Prospectus', 'Official Academic Prospectus, Disciplines, Infrastructure & Campus Life', 'assets/uploads/2025/10/new-update/Prospectus.pdf'),
('49', 'Admission Process & Guidelines', 'admission-process-guidelines', '<div class=\'document-content-summary\'><p>Comprehensive institutional guidelines outlining candidate registration, qualifying document scrutiny, counseling schedule, merit list criteria, and fee deposition for candidates seeking admission.</p><ul><li>Clear step-by-step instructions for online and campus counter admissions.</li><li>Checklist of required certificates, mark-sheets, and identity proofs.</li><li>Fee payment modalities, installment schedules, and receipt generation.</li><li>Reporting instructions, induction schedules, and commencement dates.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Admission-Process&Guidelines.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Comprehensive institutional guidelines outlining candidate registration, qualifying document scrutiny, counseling schedule, merit list criteria, and fee deposition for candidates seeking admission.', 'published', '2026-09-12 11:02:16', 'Admission Process & Guidelines', 'Step-by-Step Admission Procedure, Verification Norms & Schedule', 'assets/uploads/2025/10/new-update/Admission-Process&Guidelines.pdf'),
('50', 'Fee Refund Policy', 'fee-refund-policy', '<div class=\'document-content-summary\'><p>Official policy governing the procedure, timelines, deductions, and processing of fee refunds for candidates seeking cancellation or withdrawal of admission as per UGC and statutory council regulations.</p><ul><li>Standardized refund slabs based on formal withdrawal application submission dates.</li><li>Deduction rules and processing mechanism through banking channels.</li><li>Refund procedure for caution money and hostel/transport deposits.</li><li>Grievance redressal channel for admission cancellation requests.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Fee-Refund-Policy-2024-25.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official policy governing the procedure, timelines, deductions, and processing of fee refunds for candidates seeking cancellation or withdrawal of admission as per UGC and statutory council regulations.', 'published', '2026-09-12 11:02:16', 'Fee Refund Policy', 'University Fee Cancellation & Refund Regulations Compliant with UGC Norms', 'assets/uploads/pdf/Fee-Refund-Policy-2024-25.pdf'),
('51', 'Research & Development Cell (RDC)', 'research-development-cell', '<div class=\'document-content-summary\'><p>Documentation outlining the objectives, organizational hierarchy, and operational framework of the University Research &amp; Development Cell fostering high-impact research, external grants, and technology innovation.</p><ul><li>Coordination of sponsored research projects with DST, SERB, ICMR, and AICTE.</li><li>Facilitation of multidisciplinary research groups and innovation clusters.</li><li>Research seed grants for young faculty and doctoral scholars.</li><li>Incentive schemes for SCI/Scopus indexed journal publications and patents.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/research&developmentcell.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Documentation outlining the objectives, organizational hierarchy, and operational framework of the University Research & Development Cell fostering high-impact research, external grants, and technology innovation.', 'published', '2026-09-12 11:02:16', 'Research & Development Cell (RDC)', 'Research Promotion, Project Grants, Publications & Innovations', 'assets/uploads/2025/10/new-update/research&developmentcell.pdf'),
('52', 'University Incubation Centre', 'incubation-centre', '<div class=\'document-content-summary\'><p>Overview of the University Technology Business Incubation Centre providing seed funding, mentorship, prototyping labs, and legal/IPR advisory to budding student and faculty startups.</p><ul><li>Plug-and-play co-working spaces equipped with high-speed internet and conference rooms.</li><li>Access to venture capitalists, angel investors, and government startup grants.</li><li>Mentorship from successful tech entrepreneurs, alumni founders, and industry leaders.</li><li>Assistance with company incorporation, patenting, and commercial pilot launches.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/incubation-centre.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Overview of the University Technology Business Incubation Centre providing seed funding, mentorship, prototyping labs, and legal/IPR advisory to budding student and faculty startups.', 'published', '2026-09-12 11:02:16', 'University Incubation Centre', 'Startup Ecosystem, Innovation Hub, Mentorship & Entrepreneurship Support', 'assets/uploads/pdf/incubation-centre.pdf'),
('53', 'University Research Policy', 'research-policy', '<div class=\'document-content-summary\'><p>Comprehensive policy governing research standards, ethical clearances, intellectual property management, patent filings, research incentives, and collaborative research initiatives at SRKU.</p><ul><li>Code of ethics in scientific research and academic publishing.</li><li>Intellectual Property Rights (IPR) filing support and patent commercialization.</li><li>Financial incentives for high-impact research publications and books.</li><li>Guidelines for collaborative research with national and international bodies.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/university_research_policy.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Comprehensive policy governing research standards, ethical clearances, intellectual property management, patent filings, research incentives, and collaborative research initiatives at SRKU.', 'published', '2026-09-12 11:02:16', 'University Research Policy', 'Institutional Guidelines for Ethics, Publications, IPR & Seed Funding', 'assets/uploads/pdf/university_research_policy.pdf'),
('54', 'Central Facilities for Research and Development', 'central-facilities-research', '<div class=\'document-content-summary\'><p>Overview of high-end analytical equipment, computational clusters, central research labs, animal house, and specialized instrumentation accessible to university researchers and doctoral scholars.</p><ul><li>Advanced analytical instrumentation across Pharmacy, Medical, and Science labs.</li><li>High-performance computing laboratory and simulation software tools.</li><li>CPCSEA approved Animal House and Central Biosafety facilities.</li><li>Open access facility usage guidelines for scholars and faculty.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Central-Facilities-for-Research-and-Development.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Overview of high-end analytical equipment, computational clusters, central research labs, animal house, and specialized instrumentation accessible to university researchers and doctoral scholars.', 'published', '2026-09-12 11:02:16', 'Central Facilities for Research and Development', 'Advanced Instrumentation, Central Computing & Laboratory Infrastructure', 'assets/uploads/pdf/Central-Facilities-for-Research-and-Development.pdf'),
('55', 'Ethics Board to Maintain Research Integrity', 'ethics-board', '<div class=\'document-content-summary\'><p>Constitution and code of practice of the Institutional Ethics Board monitoring research integrity, ethical clearance for human and animal trials, and anti-plagiarism compliance across all disciplines.</p><ul><li>Ethical scrutiny of biomedical, clinical, and pharmacological research proposals.</li><li>Strict adherence to ICMR, CPCSEA, and global bioethics guidelines.</li><li>Plagiarism checking protocol for dissertations, papers, and synopsis.</li><li>Promoting transparent, responsible, and ethical conduct in scientific inquiry.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Constitution-of-Ethics-Board.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Constitution and code of practice of the Institutional Ethics Board monitoring research integrity, ethical clearance for human and animal trials, and anti-plagiarism compliance across all disciplines.', 'published', '2026-09-12 11:02:16', 'Ethics Board to Maintain Research Integrity', 'Institutional Ethics Committee, Bioethics & Research Integrity Guidelines', 'assets/uploads/2025/10/new-update/Constitution-of-Ethics-Board.pdf'),
('56', 'Consultancy Projects & Guidelines', 'consultancy-projects', '<div class=\'document-content-summary\'><p>Framework for faculty and departments offering specialized industrial consultancy, testing services, corporate training, and technical advisory to government and private sector organizations.</p><ul><li>Revenue sharing, institutional overheads, and project administration norms.</li><li>Material testing, drug formulation analysis, and software development services.</li><li>Corporate customized training and skill development programs.</li><li>MoUs with leading industrial firms and technology corporations.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/consultancy-projects.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Framework for faculty and departments offering specialized industrial consultancy, testing services, corporate training, and technical advisory to government and private sector organizations.', 'published', '2026-09-12 11:02:16', 'Consultancy Projects & Guidelines', 'Industry Consultancy, Technical Solutions & Technology Transfer', 'assets/uploads/pdf/consultancy-projects.pdf'),
('57', 'Admission Policy for Ph.D. Programme', 'phd-admission-policy', '<div class=\'document-content-summary\'><p>Official university ordinance governing Doctor of Philosophy (Ph.D.) admissions, eligibility standards, coursework structure, Research Advisory Committee (RAC) evaluations, and thesis submission.</p><ul><li>Eligibility norms compliant with UGC / AICTE and Apex Regulatory Councils.</li><li>Doctoral Entrance Test (DET) guidelines and interview evaluation criteria.</li><li>Mandatory Pre-Ph.D. coursework, research ethics, and publication mandates.</li><li>Research synopsis approval, progress review, and dissertation examination.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Admission_policy_for_Ph.D.Programme.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official university ordinance governing Doctor of Philosophy (Ph.D.) admissions, eligibility standards, coursework structure, Research Advisory Committee (RAC) evaluations, and thesis submission.', 'published', '2026-09-12 11:02:16', 'Admission Policy for Ph.D. Programme', 'UGC Minimum Standards for the Award of Ph.D. Degree Ordinance', 'assets/uploads/pdf/Admission_policy_for_Ph.D.Programme.pdf'),
('58', 'Constitution of Research Advisory Committee (RAC)', 'constitution-of-research-advisory-committee', '<div class=\'document-content-summary\'><p>Mandate, composition, and functions of candidate-specific Research Advisory Committees (RAC) overseeing doctoral research milestones from topic approval to thesis defense.</p><ul><li>Three-member expert committee constituted for every registered Ph.D. scholar.</li><li>Evaluation of half-yearly research progress reports and laboratory experiments.</li><li>Guidance on pre-submission presentation, thesis drafting, and viva voce.</li><li>Resolution of research bottlenecks and supervisor coordination.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/constitution-of-research-advisory-committee.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Mandate, composition, and functions of candidate-specific Research Advisory Committees (RAC) overseeing doctoral research milestones from topic approval to thesis defense.', 'published', '2026-09-12 11:02:16', 'Constitution of Research Advisory Committee (RAC)', 'Doctoral Monitoring Panels, Guide Allocation & Half-Yearly Research Reviews', 'assets/uploads/pdf/constitution-of-research-advisory-committee.pdf'),
('59', 'Details About Ph.D. Scholars Currently Enrolled', 'phd-scholars-currently-enrolled', '<div class=\'document-content-summary\'><p>Official university registry and public disclosure of active doctoral research scholars pursuing Ph.D. programmes along with their department, guide details, and registration session.</p><ul><li>Public compliance record as per UGC minimum standard disclosure mandates.</li><li>Discipline-wise distribution of currently enrolled doctoral scholars.</li><li>Details of approved research supervisors and recognized guides.</li><li>Research progress monitoring and Departmental Research Committee tracking.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Details-about-Ph.D.Scholars-Currently-Enrolled.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official university registry and public disclosure of active doctoral research scholars pursuing Ph.D. programmes along with their department, guide details, and registration session.', 'published', '2026-09-12 11:02:16', 'Details About Ph.D. Scholars Currently Enrolled', 'Official Registry of Active Doctoral Research Scholars across Disciplines', 'assets/uploads/pdf/Details-about-Ph.D.Scholars-Currently-Enrolled.pdf'),
('60', 'Alumni Registration Certificate', 'alumni-registration-certificate', '<div class=\'document-content-summary\'><p>Official registration certificate under the Societies Registration Act legalizing the Sarvepalli Radhakrishnan University Alumni Association for global networking, student mentorship, and philanthropic contributions.</p><ul><li>Registered under the statutory Societies Registration framework.</li><li>Formal recognition of the SRKU Global Alumni Network.</li><li>Governance structure, founding patrons, and executive body members.</li><li>Enabling alumni chapters in Delhi, Mumbai, Bengaluru, and international hubs.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/AluminaiRegistrationCertificate.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official registration certificate under the Societies Registration Act legalizing the Sarvepalli Radhakrishnan University Alumni Association for global networking, student mentorship, and philanthropic contributions.', 'published', '2026-09-12 11:02:16', 'Alumni Registration Certificate', 'Official Legal Registration Certificate of SRKU Alumni Association', 'assets/uploads/2025/10/new-update/AluminaiRegistrationCertificate.pdf'),
('61', 'Alumni Bylaws & Constitution', 'alumni-bylaws', '<div class=\'document-content-summary\'><p>Constitution and bylaws governing membership categories, election of executive office bearers, annual general meetings, endowment funds, and outreach activities of the SRKU Alumni Association.</p><ul><li>Membership eligibility criteria for graduates of all constituent colleges.</li><li>Procedure for election of President, Vice President, Secretary, and Treasurer.</li><li>Creation of student scholarship funds and industry innovation grants.</li><li>Organization of annual alumni re-unions and distinguished alumni awards.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/alumni.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Constitution and bylaws governing membership categories, election of executive office bearers, annual general meetings, endowment funds, and outreach activities of the SRKU Alumni Association.', 'published', '2026-09-12 11:02:16', 'Alumni Bylaws & Constitution', 'Rules, Regulations & Code of Operations of Alumni Association', 'assets/uploads/2025/10/new-update/alumni.pdf'),
('62', 'Alumni Committee', 'alumni-committee', '<div class=\'document-content-summary\'><p>Official composition of the University Alumni Committee coordinating institutional engagements, career talks, mentorship pairing, and networking forums between alumni and current scholars.</p><ul><li>Senior faculty and distinguished alumni representing diverse faculties.</li><li>Coordination of guest lectures, corporate seminars, and internship pipelines.</li><li>Quarterly meetings reviewing alumni chapter expansions and initiatives.</li><li>Dedicated alumni liaison desk and portal administration.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/Alumni-committee.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official composition of the University Alumni Committee coordinating institutional engagements, career talks, mentorship pairing, and networking forums between alumni and current scholars.', 'published', '2026-09-12 11:02:16', 'Alumni Committee', 'Executive Committee Members & Departmental Alumni Coordinators', 'assets/uploads/2025/10/new-update/Alumni-committee.pdf'),
('63', 'Right to Information (RTI)', 'rti', '<div class=\'document-content-summary\'><p>Official notification designating the Public Information Officer (PIO), Assistant Public Information Officer (APIO), and First Appellate Authority of SRKU under the Right to Information Act, 2005.</p><ul><li>Statutory public disclosure under Section 4(1)(b) of the RTI Act 2005.</li><li>Name, designation, and official contact coordinates of appointed PIO and Appellate Authority.</li><li>Prescribed RTI application fee modalities and procedure for filing appeals.</li><li>Commitment to institutional transparency and good governance.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/rti.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official notification designating the Public Information Officer (PIO), Assistant Public Information Officer (APIO), and First Appellate Authority of SRKU under the Right to Information Act, 2005.', 'published', '2026-09-12 11:02:16', 'Right to Information (RTI)', 'Public Information Officers, Appellate Authority & RTI Guidelines', 'assets/uploads/2025/10/new-update/rti.pdf'),
('64', 'Ph.D. Scholars Pursuing', 'phd-pursuing', '<div class=\'document-content-summary\'><p>Public disclosure record of doctoral research scholars currently enrolled and pursuing their Doctor of Philosophy (Ph.D.) degree under approved research supervisors across academic departments.</p><ul><li>Scholar registration details, enrolment years, and research supervisor allocations.</li><li>Department-wise distribution across Engineering, Pharmacy, Management, and Sciences.</li><li>Progress monitoring in accordance with UGC Minimum Standards regulations.</li><li>Public compliance record for transparency in research admissions.</li></ul><p><a href=\'http://localhost/assets/uploads/phd/Phd Pursuing.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Public disclosure record of doctoral research scholars currently enrolled and pursuing their Doctor of Philosophy (Ph.D.) degree under approved research supervisors across academic departments.', 'published', '2026-09-12 11:02:16', 'Ph.D. Scholars Pursuing', 'Comprehensive Directory of Enrolled Doctoral Research Candidates', 'assets/uploads/pdf/Phd-Pursuing.pdf'),
('65', 'Ph.D. Scholars Awarded / Completed', 'phd-completed', '<div class=\'document-content-summary\'><p>Official university registry of research scholars successfully awarded Doctor of Philosophy (Ph.D.) degrees upon recommendation of the external evaluation board and viva-voce examination.</p><ul><li>Comprehensive historical list of conferred doctorate degree recipients.</li><li>Research thesis titles, supervising faculty, and graduation sessions.</li><li>Notification numbers and gazette references for academic verification.</li><li>Benchmark scholarly output contributing to university research citations.</li></ul><p><a href=\'http://localhost/assets/uploads/phd/Phd Completed.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official university registry of research scholars successfully awarded Doctor of Philosophy (Ph.D.) degrees upon recommendation of the external evaluation board and viva-voce examination.', 'published', '2026-09-12 11:02:16', 'Ph.D. Scholars Awarded / Completed', 'Official Registry of Conferred Doctor of Philosophy Degrees', 'assets/uploads/pdf/Phd-Completed.pdf'),
('66', 'NIRF 2026 Institutional Report', 'nirf-2026', '<div class=\'document-content-summary\'><p>Official submission data and institutional disclosure submitted by Sarvepalli Radhakrishnan University to the National Institutional Ranking Framework (NIRF), Ministry of Education, Government of India.</p><ul><li>Student strength, sanctioned intakes, and graduation outcome parameters.</li><li>Faculty qualifications, student-teacher ratios, and research publications.</li><li>Financial resources, capital expenditures, and operational infrastructure spends.</li><li>Facilities for physically challenged students and public perception indices.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/nirf/NIRF-2026.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official submission data and institutional disclosure submitted by Sarvepalli Radhakrishnan University to the National Institutional Ranking Framework (NIRF), Ministry of Education, Government of India.', 'published', '2026-09-12 11:02:16', 'NIRF 2026 Institutional Report', 'National Institutional Ranking Framework (NIRF) 2026 Disclosure', 'assets/uploads/2026/07/NIRF-2026.pdf'),
('67', 'University Job Vacancies & Recruitment', 'vacancy', '<div class=\'document-content-summary\'><p>Official university recruitment announcement and employment advertisement for Professor, Associate Professor, Assistant Professor, and administrative cadre vacancies across university faculties.</p><ul><li>Vacancies across Engineering, Pharmacy, Management, Medicine, and Law.</li><li>Prescribed qualifications and pay scales as per UGC, AICTE, and state council norms.</li><li>Application submission modalities, selection interview schedule, and deadlines.</li><li>Equal opportunity employer offering attractive research incentives and academic growth.</li></ul><p><a href=\'http://localhost/assets/uploads/2025/10/new-update/SRKU-Requirement-Paper.pdf\' class=\'btn btn-danger\' target=\'_blank\'>Download Official PDF</a></p></div>', 'Official university recruitment announcement and employment advertisement for Professor, Associate Professor, Assistant Professor, and administrative cadre vacancies across university faculties.', 'published', '2026-09-12 11:02:16', 'University Job Vacancies & Recruitment', 'Faculty & Administrative Staff Recruitment Notification & Eligibility', 'assets/uploads/pdf/SRKU-Requirement-Paper.pdf'),
('68', 'SRK University Exam Time Table 2024-25 & 2026', 'exam-time-table', 'Official Examination Schedules and Time Tables for all faculties and courses at Sarvepalli Radhakrishnan University (SRKU), Bhopal.', 'Official Examination Schedules and Time Tables for all departments and courses at Sarvepalli Radhakrishnan University (SRKU), Bhopal.', 'published', '2026-09-12 11:40:12', 'Examination Time Table', 'Controller of Examinations &middot; Official Date Sheets', NULL);
INSERT INTO `departments` (`id`, `name`, `category`, `slug`, `icon`, `image`, `banner_img`, `description`, `dean_name`, `dean_designation`, `dean_photo`, `dean_message`, `contact_no`, `approvals`, `established_year`, `status`) VALUES
('47', 'RKDF Institute of Science and Technology (1995)', 'Engineering & Technology', 'rkdf-institute-of-science-and-technology', 'fas fa-microchip', 'assets/uploads/constituent-units/rkdf-institute-of-science-and-technology.webp', 'assets/uploads/constituent-units/rkdf-institute-of-science-and-technology.webp', 'RKDF Institute of Science and Technology is a pioneer technical institution offering AICTE approved Diploma Polytechnic, B.Tech in multiple disciplines, M.Tech/M.E. in multiple specialized fields, MCA, MBA, and Ph.D. programs with cutting-edge computing, AI(DSA), and advanced mechanical laboratories.', 'Director', 'Director', '', 'SRK University RKDF Institute of Science & Technology is a premier institute for professional studies. This institute has achieved ladder of engineering excellence since it\'s inception in 1995 & is recognized as one of the leading professional institutes in Madhya Pradesh, where students acquire technical & professional skills with cutting edge technology, knowledge & high moral standards. The growth achieved by this institution is significant. The institute is committed to offer quality technical education by adopting principle of mutual trust, fairness & positive orientation. The management, faculty members & supporting staff is committed to fulfill the expectations of all the stake holders i.e. students, parent, corporate community & society. The students are benefited with excellent infrastructure, dedicated faculty members & excellent track record of placement in corporate world. The vision of our faculties and their dedication to the cause of technical education combined with their dynamic approach to leadership has made a telling difference to the growth of the college. Our graduate students are selected in top notch organization, working in the field of software, energy, infrastructure, robotics & automation in fortune 500 companies of western world as well as MNCs of India. In the years to come RKDF Institute of Science & Technology shall play a significant role in the technology sector for developing trained & skilled human resources to serve the nation for better economic performance & growth.', '0755-4700983, 7024144981', 'AICTE, UGC', '1995', 'active'),
('48', 'RKDF IST-MCA (1999)', 'Computer Applications & IT', 'rkdf-institute-science-technology-mca', 'fas fa-laptop-code', 'assets/uploads/constituent-units/rkdf-institute-science-technology-mca.webp', 'assets/uploads/constituent-units/rkdf-institute-science-technology-mca.webp', 'RKDF IST-MCA is dedicated to advanced postgraduate computing education, enterprise software development, cloud infrastructure, AI systems, and cyber security.', 'Dr. Varsha Namdeo', 'Dean RKDFIST (MCA) | Qualification : Ph. D, MCA, M.Tech (CSE) | Total Exp.: 16 Years | Total Publication: 21', 'assets/uploads/leaders/varsha-namdeo.jpg', 'Dr. Varsha Namdeo\nDean RKDFIST (MCA)\nQualification : Ph. D, MCA, M.Tech (CSE)\nTotal Exp.: 16 Years\nTotal Publication: 21\n\nSRK University, Bhopal(M.P.) It gives me immense pleasure to present before you a brief of our vision and efforts. Our institute is one of the leading institutes which have taken a leap forward in the quality technical education. The vision of the institute is, “To produce world class engineers for converting global challenges into opportunities through value embedded quality technical education.” To achieve this, we have to develop this institute as a Centre of Academic excellence of higher learning in the fields of engineering and technology. All the efforts are focused towards fulfillment of vision and mission. Apart from delivering excellent academic content and development of skills through practical experiences, the students are encouraged to develop through bridge courses by interacting with resource persons. Various modules are arranged so that they are “made ready” for the varied opportunities and challenges with confidence. Through ‘Tutor Guardian Scheme’ for every 20 students, teachers help them in resolving academic as well as domestic problems and inspire them for achieving excellent academic career and overall personal development. We are in constant touch with parents and keep informing the performance of their wards through correspondence and dialogues. Placement of young energetic budding engineers is of prime importance to all of us. A systematic development in soft skills and overall confidence building through weekly programs is unique of our institute. Ultimately, our student will be a holistic person. Here at SRK University, we are committed to impart necessary skills and knowledge to our students in best possible manner, in good spirit and in good environment by allowing them to dream high and help them to achieve the same. Industry demands technocrat-leaders to serve various sectors. We all stake holders, including you, have to work in this direction to fulfill the dream INDIA-2020.', '0755-4700983, 7024144981', 'AICTE, UGC', '1999', 'active'),
('49', 'RKDF Institute of Management (2003)', 'Management & Commerce', 'rkdf-institute-of-management', 'fas fa-chart-line', 'assets/uploads/constituent-units/rkdf-institute-of-management.webp', 'assets/uploads/constituent-units/rkdf-institute-of-management.webp', 'RKDF Institute of Management is a premier business school delivering Full-Time MBA with diverse super-specializations including Marketing, Finance, HR, Supply Chain, Hospital Administration, Retail, and Event Management, along with doctoral Ph.D. research.', 'Dr. Pragya Sharma', 'Director, Department of Management (Ph.D, MBA, B.Ed., M.Ed., M.A.)', 'assets/uploads/leaders/dr-pragya-sharma.jpg', 'Dear Students, Faculty, and Staff,\n\nI am delighted to welcome you to RKDF Institute of Management, SRK University, Bhopal. As the Director of this esteemed institution, I am committed to fostering a learning environment that is both challenging and supportive.\n\nAt RKDF Institute of Management, we believe in empowering our students with the knowledge, skills, and values they need to succeed in their careers and make a positive impact on the world. Our dedicated faculty members are committed to providing a well-rounded education that prepares our students for the challenges and opportunities of the 21st century.\n\nWe offer a wide range of academic programs and extracurricular activities to help our students develop their full potential. Whether you are interested in finance, marketing, human resources, or entrepreneurship, we have something to offer you.\n\nI invite you to explore our website and learn more about all that RKDF Institute of Management has to offer. Thank you for being a part of our community. I look forward to seeing the great things you will achieve.\n\nWarm regards,\nDr. Pragya Sharma\nDirector, RKDF Institute of Management\nSRK University, Bhopal', '0755-4700983, 7024144981', 'AICTE, UGC', '2003', 'active'),
('50', 'RKDF Institute of Business Management (2006)', 'Management & Commerce', 'rkdf-institute-of-business-management', 'fas fa-briefcase', 'assets/uploads/constituent-units/rkdf-institute-of-business-management.webp', 'assets/uploads/constituent-units/rkdf-institute-of-business-management.webp', 'RKDF Institute of Business Management delivers postgraduate MBA programs focused on leadership development, business analytics, corporate consulting, and entrepreneurship.', 'Dr. Sushil Singh', 'Director (PhD., MBA, M.Sc, MA, PGDCA - Total Exp. 39 Years)', 'assets/uploads/leaders/sushil-singh.jpg', 'In today’s dynamic and highly competitive global marketplace, students must be equipped not only with academic knowledge but also with practical skills to seize emerging opportunities. At the core of our vision is the belief that management education plays a vital role in shaping future leaders—individuals who can drive innovation, lead responsibly, and build resilient organizations.\n\nOur management courses offer a comprehensive education in the principles and practices essential for effective business administration and leadership. They aim to develop students\' competencies in key areas such as strategic planning, organizational behavior, finance, marketing, and human resources. With a strong focus on entrepreneurial thinking and global business trends, the program prepares students for successful careers across diverse industries or for further studies in management. Ethical values and social responsibility are deeply embedded in the curriculum, fostering leaders who strive for both business excellence and positive societal impact.\n\nAs part of SRK University, our faculty and students actively engage with industry experts through regular visits, case-based learning, and live projects. We offer both undergraduate and postgraduate programs with industry-aligned specializations, empowering students to build promising careers. The institute emphasizes the integration of innovation and entrepreneurship, supported by world-class infrastructure and a vibrant, dynamic faculty dedicated to nurturing future leaders. On behalf of the entire institute, I warmly invite you to visit our campus and become a part of this transformational journey.', '0755-4700983, 7024144981', 'AICTE, UGC', '2006', 'active'),
('51', 'Department of Management', 'Management & Commerce', 'department-of-management', 'fas fa-dolly-flatbed', 'assets/uploads/constituent-units/department-of-management.webp', 'assets/uploads/constituent-units/department-of-management.webp', 'Department of Management specializes in advanced Master of Business Administration programs including MBA in Logistics & Supply Chain Management with global industry partnerships.', NULL, 'Dean & Principal', NULL, NULL, '0755-4700983, 7024144981', 'AICTE, UGC', '2015', 'active'),
('52', 'RKDF College of Pharmacy (1995)', 'Pharmacy', 'rkdf-college-of-pharmacy', 'fas fa-pills', 'assets/uploads/constituent-units/rkdf-college-of-pharmacy.webp', 'assets/uploads/constituent-units/rkdf-college-of-pharmacy.webp', 'RKDF College of Pharmacy is a premier PCI approved institution offering D.Pharmacy, B.Pharmacy, M.Pharmacy across multiple disciplines (Pharmaceutics, Pharmacology, Pharmacognosy, Pharmaceutical Chemistry, Industrial Pharmacy), and doctoral Ph.D. research.', 'Dr Nishi Prakash Jain', 'Principal (Ph.D, M.Pharma)', 'assets/uploads/leaders/principal-nishi-prakash-jain.jpg', 'It gives me immense pleasure to extend a warm welcome to all of you to the virtual domain of RKDF College of Pharmacy. As we continue to navigate through unprecedented times, our commitment to excellence in education and research remains unwavering. At RKDF College of Pharmacy, we strive to create a conducive environment where learning transcends boundaries. Our dedicated faculty members, state-of-the-art infrastructure, and innovative teaching methodologies are geared towards nurturing the holistic development of our students. As we embark on this journey together, I urge each one of you to embrace challenges, explore new horizons, and strive for academic and personal excellence. Let us uphold the values of integrity, discipline, and compassion as we work towards realizing our collective vision of a brighter tomorrow. I encourage you to explore our website to discover the myriad opportunities and resources available to you. Together, let us embark on a transformative journey towards knowledge, innovation, and societal impact. Best wishes and Warm regards.', '0755-4700983, 7024144981', 'PCI, AICTE, UGC', '1995', 'active'),
('53', 'Sarvepalli Radhakrishnan College of Pharmacy (2018)', 'Pharmacy', 'sarvepalli-radhakrishnan-college-of-pharmacy', 'fas fa-prescription-bottle-alt', 'assets/uploads/constituent-units/sarvepalli-radhakrishnan-college-of-pharmacy.webp', 'assets/uploads/constituent-units/sarvepalli-radhakrishnan-college-of-pharmacy.webp', 'Sarvepalli Radhakrishnan College of Pharmacy is dedicated to high-standard pharmaceutical education, offering D.Pharmacy, B.Pharmacy, and M.Pharmacy in Pharmaceutics, Pharmacology, Pharmacognosy, Pharmaceutical Analysis, and Pharmaceutical Chemistry.', 'Dr. Rishikesh Sharma', 'Principal (PhD, M.Pharma)', 'assets/uploads/leaders/principal-rishikesh-sharma.jpg', 'Sarvepalli Radhakrishnan College of Pharmacy Bhopal, is committed to provide quality education and has an excellent infrastructure with highly qualified teaching staff ,who are committed to providing an outstanding education experience to students in the field of pharmacy. We insist positive value system that shapes students attitude and conduct that provides a strong foundation for them to tackle the changes in pharmacy field .Our college proclaims a powerful vision for the future of pharmacy students and has a deep understanding of our obligations and commitments to help share the students lives. Our college has spacious laboratories and well equipped with sophisticated instruments. To our credit we have highly qualified ,experienced and dedicated teaching faculty. The scope of pharmacy practice includes more traditional roles such as compounding and dispensing medications, and it also includes more modern services related to health care, including clinical services, reviewing medications for safety and efficacy, and providing drug information. Pharmacists, therefore, are the experts on drug therapy and are the primary health professionals who optimize use of medication for the benefit of the patients. In its investigation of herbal and chemical ingredients, the work of the pharmacy may be regarded as a precursor of the modern pharmaceutical field, prior to the formulation of the scientific method.', '0755-4700983, 7024144981', 'PCI, UGC', '2018', 'active'),
('54', 'Dr. APJ Abdul Kalam College of Pharmacy (2018)', 'Pharmacy', 'dr-apj-abdul-kalam-college-of-pharmacy-srk-bhopal', 'fas fa-flask', 'assets/uploads/constituent-units/dr-apj-abdul-kalam-college-of-pharmacy-srk-bhopal.webp', 'assets/uploads/constituent-units/dr-apj-abdul-kalam-college-of-pharmacy-srk-bhopal.webp', 'Dr. APJ Abdul Kalam College of Pharmacy provides PCI recognized D.Pharmacy, B.Pharmacy, and M.Pharmacy in Pharmaceutics, Pharmacology, Pharmacognosy, Pharmaceutical Chemistry, and Drug Regulatory Affairs (DRA).', 'Dr. Prashant Soni', 'Principal (MPH, Ph.D)', 'assets/uploads/leaders/prashant-soni.jpg', 'Compliments from Dr APJ Abdul Kalam College of Pharmacy Bhopal (M.P.). The world is escalating not in numbers but in quality. The enhanced quality has increased the life anticipation and increased and demand for medicines both for treatment and cure. With improved education, living standard has changed increasing the use and demand for pharmaceuticals. Today Pharma industry has a turnover of billions of dollars. India is not only producing medicines for domestic market but exporting it in a big way all this will lead to make pharmacy profession more attractive. Dr APJ Abdul Kalam College of Pharmacy Bhopal (M.P.) is one such new pharmaceutical teaching institute started in Bhopal with an ambitious vision, “to be among the leading professional training and research institutions in the field of Pharmacy in India” and mission, “to provide excellence education and training to the upcoming pharmacy professionals by creating an environment conducive for effective and sustainable learning”. We motivated not only to provide quality education but also to create capable, confident and skilled professionals. Our focus is therefore, to be the leading pharmacy professional training and research institute that imparts eminence education on overall personality development. We always believe in building a strong knowledgeable nation. I welcome to all in the immense atmosphere of Dr APJ Abdul Kalam College of Pharmacy Bhopal (M.P.).', '0755-4700983, 7024144981', 'PCI, UGC', '2018', 'active'),
('55', 'Sri Sai College of Pharmacy (2019)', 'Pharmacy', 'sri-sai-college-of-pharmacy-srk-bhopal', 'fas fa-capsules', 'assets/uploads/constituent-units/sri-sai-college-of-pharmacy-srk-bhopal.webp', 'assets/uploads/constituent-units/sri-sai-college-of-pharmacy-srk-bhopal.webp', 'Sri Sai College of Pharmacy offers PCI approved D.Pharmacy, B.Pharmacy, and M.Pharmacy in Pharmaceutics, Pharmacology, Quality Assurance, Pharmaceutical Chemistry, and Pharmacognosy.', 'Dr Ruchi Choubey', 'Principal (Ph.D, M.Pharm)', 'assets/uploads/leaders/principal-ruchi-choubey.jpg', 'It is my pleasure to introduce you the Sri Sai College of Pharmacy. We have started our journey in 2019 and college is committed to provide a favourable environment to nurture the students in the basics and advance knowledge of Pharmacy. We are committed to a complete development of students. We equally care our student’s extracurricular as well as co-curricular activities so that they can be successful in their area of interest.', '0755-4700983, 7024144981', 'PCI, UGC', '2019', 'active'),
('56', 'Sarvepalli Radhakrishnan Institute of Pharmaceutical Sciences (2023)', 'Pharmacy', 'sarvepalli-radhakrishnan-institute-of-pharmaceutical-science', 'fas fa-tablets', 'assets/uploads/constituent-units/sarvepalli-radhakrishnan-institute-of-pharmaceutical-science.webp', 'assets/uploads/constituent-units/sarvepalli-radhakrishnan-institute-of-pharmaceutical-science.webp', 'Sarvepalli Radhakrishnan Institute of Pharmaceutical Sciences offers modern D.Pharmacy and B.Pharmacy degree programs equipped with sophisticated analytical instruments and formulation labs.', 'Dr. Kailash Kumar Pathak', 'Principal (Ph.D, M.Pharmacy)', 'assets/uploads/leaders/principal-kailash-pathak.jpg', 'Today the role of college is not only to pursue academic excellence, but also to motivate and empower its students to be lifelong learners and productive members of an ever-changing global society. Our ambition is to ignite the flame of success in future challenges that need to be encountered with motivation, determination and commitment. We truly have a fantastic group with dedicated and highly skilled staff, excellent resources and the infrastructure with bright students to work with.', '0755-4700983, 7024144981', 'PCI, UGC', '2023', 'active'),
('57', 'R. N. Kapoor Memorial Institute of Pharmaceutical Sciences (2023)', 'Pharmacy', 'r-n-kapoor-memorial-institute-of-pharmaceutical-sciences-srk-university', 'fas fa-mortar-pestle', 'assets/uploads/constituent-units/r-n-kapoor-memorial-institute-of-pharmaceutical-sciences-srk-university.webp', 'assets/uploads/constituent-units/r-n-kapoor-memorial-institute-of-pharmaceutical-sciences-srk-university.webp', 'R. N. Kapoor Memorial Institute of Pharmaceutical Sciences delivers top-tier D.Pharmacy and B.Pharmacy programs fostering clinical and community pharmacy practice.', 'Dr. Yogesh Shivhare', 'Principal (Ph.D, M.Pharmacy)', 'assets/uploads/leaders/principal-yogesh-shivhare.jpg', 'Education is a shared commitment between dedicated teachers, motivated students and enthusiastic parents with high expectations. I believe my role as an educator is to guide and nurture the next generation to establish skills to achieve health, respect, prosperity and fulfillment. I am passionate about students being empowered to succeed. As Principal, I use all tools available to inspire staff, students and community to work together to promote student achievement and well-being. I am an avid supporter of effective and innovative professional development that encourages teachers and principals to be reflective and to continuously examine our practice to provide quality teaching and learning for each student. My role as Principal is to keep up with latest trends and research and be an active partner in the College’s professional development. The ability to be innovative and creative is important to me. I enjoy being challenged and inspired by the people around me. I aim to enthuse and challenge staff and students to also be inventive and imaginative in their learning and day to day tasks. We also know how important it is to build strong parent-teacher relationships as we recognize what a pivotal role the teacher plays in the student’s life. As a result, we encourage parents to be active participants in college life and we welcome you to be part of our many family events and class activities. Once again, thank you for your interest in our college and we look forward to you and your family becoming part of our international community of learners.', '0755-4700983, 7024144981', 'PCI, UGC', '2023', 'active'),
('58', 'RKDF College of Nursing (2003)', 'Nursing & Healthcare', 'rkdf-college-of-nursing', 'fas fa-user-nurse', 'assets/uploads/constituent-units/rkdf-college-of-nursing.webp', 'assets/uploads/constituent-units/rkdf-college-of-nursing.webp', 'RKDF College of Nursing is an INC and MPNRC recognized center offering B.Sc Nursing, Post Basic B.Sc Nursing, GNM, M.Sc Nursing across diverse clinical specialties, NPCC (Nurse Practitioner in Critical Care), and Ph.D. with comprehensive training in on-campus multi-speciality hospital.', 'Lt.Col. Archana Selvan (Retd.)', 'Dean & Principal (Ph.D, M.Phil, M.Sc Nursing)', 'assets/uploads/leaders/archana-selvan.jpg', 'It gives me immense pleasure and honor to welcome you to RKDF College of nursing Bhopal. The nursing profession is the noblest of all profession and in immense demand globally, offering a highly rewarding career. RKDF College of nursing was established in 2003 with a vision to impart quality education to nursing students and to shape their future as professionals with an innovative and academically challenging experience in order to meet the technological revolution all over the world. Since inception it has trained & educated six batches of students and the Graduates of this college are working in India and abroad. They are also absorbed in Railways, Govt. hospitals, AIIMS, Military hospitals in Armed Forces, private & Multispecialty hospitals. The College is recognized by Indian nursing council New Delhi, M.P.State nursing registration council, Bhopal and it is also affiliated to SRK University,Bhopal for B.Sc. & M.Sc. nursing programs. The institution is known for academic excellence, outstanding results in the university examination for under and post graduate programmes. The College Offers two undergraduate programs, two postgraduate programs and Doctoral Program. Undergraduate programs are General Nursing & Midwifery (GNM) and B.Sc Nursing & Post Graduate programs are Post Basic Nursing (P.B.Nursing) and M.Sc Nursing.', '0755-4700983, 7024144981', 'INC, MPNRC, UGC', '2003', 'active'),
('59', 'RKDF Medical College, Hospital & Research Center (2014)', 'Medical & Dental Sciences', 'rkdf-medical-college', 'fas fa-hospital', 'assets/uploads/constituent-units/rkdf-medical-college.webp', 'assets/uploads/constituent-units/rkdf-medical-college.webp', 'RKDF Medical College, Hospital & Research Center is recognized by NMC and offers MBBS and MD/MS in clinical & non-clinical specializations with a multispecialty teaching hospital on campus.', 'Dr. HEMANT B. GADEKAR', 'Dean & Professor (MD, MBBS)', 'assets/uploads/leaders/hemant-dean-medical.jpg', 'We at RKDF Medical College Hospital and Research Centre welcome all those who believe in excellence, to join hands to bring up a seat of knowledge and skills devoted to impart best quality medical education and patient care with human touch. We propose to inculcate the art of medical practice in its true spirit during all our teaching and training programmes aided by adopting the most modern technology and newly evolved systems of medical education methods. Our aim is to mould the newly recruited raw trainees and transform them in to a model health care provider while they pursue the course at this institute. To achieve this objective, we are fortunate to have a supporting hand of management and a dedicated team of highly experienced faculty. A well stocked IT-enabled library will serve as a valuable learning resource. The facilities available at the attached hospital are comparable to any other tertiary care centre and have been growing by each passing day. The college administration is committed to take care of all round welfare of the students by ensuring comfortable accommodation, food requirements, recreational and sports activities and of course a ragging free campus. We are open to suggestions and meaningful inputs from all concerned will be of great help for making RKDF Medical College Hospital and Research Centre a unique place for rearing the best among best medical professionals, be it clinical practitioners, research scientists or health administrators. Perfection is our watch word and we shall always strive to attain it. May Almighty shower His blessings to strengthen our resolve.', '0755-4700983, 7024144981', 'NMC, UGC', '2014', 'active'),
('60', 'Sarvepalli Radhakrishnan College of Ayurveda, Hospital & Research Center (2021)', 'Ayush & Medical', 'sarvepalli-radhakrishnan-college-of-ayurveda', 'fas fa-leaf', 'assets/uploads/constituent-units/sarvepalli-radhakrishnan-college-of-ayurveda.webp', 'assets/uploads/constituent-units/sarvepalli-radhakrishnan-college-of-ayurveda.webp', 'Sarvepalli Radhakrishnan College of Ayurveda offers NCISM approved BAMS (Bachelor of Ayurvedic Medicine and Surgery) backed by an Ayurvedic teaching hospital, herbal botanical garden, and Panchakarma therapy suites.', 'Dr. Rakesh Kumar Pandey', 'Principal & Professor (MD Ayurved Samhita & Siddhanta)', '', 'Sarvepalli Radhakrishnan College of Ayurveda, Hospital & Research Centre extends a warm welcome to all students. Ayurvedic medicine is an ancient holistic science combining the art of healthy living and therapeutics. Our institution provides comprehensive education in BAMS through well-equipped Samhita, Rachana Sharir, Kriya Sharir, Dravyaguna, and Rasashastra laboratories along with bedside clinical exposure in our 60-bed Ayurvedic teaching hospital and active Panchakarma theatre. We inspire our scholars to imbibe classical Ayurvedic principles and modern diagnostics to serve the healthcare needs of society with compassion and professional integrity.', '0755-4700983, 7024144981', 'NCISM, Ayush, UGC', '2021', 'active'),
('61', 'RKDF Homoeopathic Medical College Hospital & Research Center (2000)', 'Ayush & Medical', 'rkdf-homoeopathic-medical-college', 'fas fa-notes-medical', 'assets/uploads/constituent-units/rkdf-homoeopathic-medical-college.webp', 'assets/uploads/constituent-units/rkdf-homoeopathic-medical-college.webp', 'RKDF Homoeopathic Medical College Hospital & Research Center is recognized by NCH and offers BHMS and MD (Homoeopathy) in specialized tracks with full clinical hospital exposure.', 'Dr. Susheela N. Choudhary', 'Professor & Principal (MD Homoeopathy)', 'assets/uploads/leaders/homoeo-principal.png', 'Our responsibility is larger than preparing students for examinations. We aim to develop clinicians who listen carefully, document responsibly, think critically, communicate with empathy and understand the importance of ethical professional conduct. Classroom teaching, laboratories, library learning, seminars, case discussions and hospital exposure are therefore treated as parts of one continuous educational journey.\n\nThe institution offers undergraduate BHMS education and postgraduate MD (Homoeopathy) learning across disciplines listed in the current NCH institutional scheme. We continue to strengthen faculty development, clinical documentation, research orientation and student mentoring so that learning remains relevant to contemporary professional expectations.\n\nI encourage every student to approach Homoeopathy with discipline and intellectual curiosity, to respect patients and colleagues, and to use the years spent on campus to build both competence and character.', '0755-4700983, 7024144981', 'NCH, Ayush, UGC', '2000', 'active'),
('62', 'RKDF Dental College & Research Center (2003)', 'Medical & Dental Sciences', 'rkdf-dental-college', 'fas fa-tooth', 'assets/uploads/constituent-units/rkdf-dental-college.webp', 'assets/uploads/constituent-units/rkdf-dental-college.webp', 'RKDF Dental College & Research Center is a DCI approved premier dental institution offering BDS and MDS across clinical disciplines with high-tech dental operatory units and oral surgery suites.', 'Dr. M.C. Prasant', 'Dean & Professor (MDS)', 'assets/uploads/leaders/dental-dean.jpg', 'Welcome to RKDF Dental College & Research Centre. Dental education today demands far more than the acquisition of technical skills. It requires a strong scientific foundation, sound clinical judgement, ethical responsibility, empathy and the ability to continue learning throughout professional life.\n\nOur academic environment is designed to help students progress from foundational knowledge and pre-clinical skill development to supervised patient care across the major specialties of dentistry. Faculty mentorship, clinical exposure, seminars, research orientation and community engagement are all parts of this journey.\n\nWe encourage every learner to approach dentistry with discipline and curiosity: to understand the evidence behind treatment, communicate respectfully with patients, work effectively with colleagues and recognise the responsibility that comes with being a healthcare professional.\n\nOur endeavour is to create an environment in which students develop not only competence, but also confidence, integrity and a lasting commitment to oral health and society.', '0755-4700983, 7024144981', 'DCI, UGC', '2003', 'active'),
('63', 'Sarvepalli Radhakrishnan College of Law (2019)', 'Law & Jurisprudence', 'sarvepalli-radhakrishnan-college-of-law', 'fas fa-balance-scale', 'assets/uploads/constituent-units/sarvepalli-radhakrishnan-college-of-law.webp', 'assets/uploads/constituent-units/sarvepalli-radhakrishnan-college-of-law.webp', 'Sarvepalli Radhakrishnan College of Law is approved by the Bar Council of India (BCI) and delivers BA. LL.B. (Hons.), LL.B., and LL.M. across specialized streams with moot court competitions and legal aid clinics.', 'Dr. Rohit Swarnkar', 'Director, Department of Law (PhD, M.Sc., LL.M., B.Ed. - Criminal Law)', 'assets/uploads/leaders/law-director-rohit-swarnkar.png', '“Justice in the life and conduct of the State is possible only as first it resides in the hearts and souls of the citizens”.\n\nSarvepalli Radhakrishnan college of Law, Sarvepalli Radhakrishnan university extends a warm and hearty welcome to all the students who joining the three years LL.B. and five years B.A.LL.B. courses. Faculty of law envision to impart value based legal education with the commitment to serve society. Our aim is inspire students to learn and understand “DHARMAM SARVAMPRATISHTITAM” (Law is supreme and not the learners). It is the law alone that brings equality amongst unequal.\n\nOur Faculty of Law environment is conductive for student to acquire requisite skill-set as we encourage participation in various curricular and co- curricular activities such as Moot court competition , Trial Advocacy, Debates, Elocution, Conference, Workshop and Classroom Discussions. Being fully conscious of the fact that law and society are interrelated and interdependent and the importance of law in the light of globalization.\n\nWith the best infrastructure and well- equipped library, we provide our students the best opportunities in exploring the world of legal knowledge. Our goal is to imbibe core values of discipline, punctuality and ethics which are quintessential to student’s progress. Our teacher have vast experience and expertise in the field of law. We aim to build legal luminaries who will uphold the rule of law.', '0755-4700983, 7024144981', 'BCI, UGC', '2019', 'active'),
('64', 'Faculty of Agriculture', 'Agriculture & Life Sciences', 'faculty-of-agriculture', 'fas fa-seedling', 'assets/uploads/constituent-units/faculty-of-agriculture.webp', 'assets/uploads/constituent-units/faculty-of-agriculture.webp', 'Faculty of Agriculture offers ICAR-aligned B.Sc. (Hons.) Agriculture, Diploma in Agriculture, and M.Sc. Agriculture across multiple disciplines with experimental crop fields, polyhouses, and soil testing labs.', 'Dr. S. K. Sharma', 'Dean & Professor (M.Sc. Agri, Ph.D)', '', 'Welcome to the Faculty of Agriculture at Sarvepalli Radhakrishnan University. Our mission is to produce agricultural graduates and scientists equipped with contemporary scientific farming techniques, sustainable agronomy, crop protection, and post-harvest technology. Surrounded by extensive research farms, modern polyhouses, and soil testing facilities, we impart rigorous field training in accordance with the ICAR 6th Deans\' Committee recommendations to lead the next agricultural transformation.', '0755-4700983, 7024144981', 'ICAR, UGC', '2016', 'active'),
('65', 'Department of Paramedical Sciences', 'Paramedical & Healthcare', 'department-of-paramedical-sciences', 'fas fa-heartbeat', 'assets/uploads/constituent-units/department-of-paramedical-sciences.webp', 'assets/uploads/constituent-units/department-of-paramedical-sciences.webp', 'Department of Paramedical Sciences provides specialized Diploma programs, UG degrees (BMLT, BPT, B.Sc Human Nutrition), PG degrees (MPT in specialized tracks, MMLT in specialized tracks), and Certificate courses with extensive practical clinical rotations in teaching hospital.', 'Dr. R. K. Saxena', 'Director & HOD (M.Sc. MLT, Ph.D)', '', 'Allied health and paramedical professionals form the indispensable clinical diagnostics and therapy pillar of modern medicine. Affiliated with our 750+ bed multispecialty hospital and diagnostic laboratories, our department provides extensive practical rotations in Medical Laboratory Technology, Radiology, Dialysis, and Physiotherapy, shaping disciplined and compassionate healthcare warriors.', '0755-4700983, 7024144981', 'MP Paramedical Council, UGC', '2015', 'active'),
('66', 'Faculty of Science', 'Allied Sciences', 'faculty-of-science', 'fas fa-atom', 'assets/uploads/constituent-units/faculty-of-science.webp', 'assets/uploads/constituent-units/faculty-of-science.webp', 'Faculty of Science offers comprehensive undergraduate B.Sc. and postgraduate M.Sc. programs in Physics, Chemistry, Mathematics, Botany, and Zoology with modern research laboratories.', NULL, 'Dean & Principal', NULL, NULL, '0755-4700983, 7024144981', 'UGC', '2015', 'active'),
('67', 'Faculty of Arts', 'Allied Sciences', 'faculty-of-arts', 'fas fa-palette', 'assets/uploads/constituent-units/faculty-of-arts.webp', 'assets/uploads/constituent-units/faculty-of-arts.webp', 'Faculty of Arts delivers B.A., M.A., MSW (Master of Social Work), B. Journalism, M. Journalism, and B.A. in Animation & Design with dynamic media studios and community projects.', NULL, 'Dean & Principal', NULL, NULL, '0755-4700983, 7024144981', 'UGC', '2015', 'active'),
('68', 'Faculty of Commerce', 'Allied Sciences', 'faculty-of-commerce', 'fas fa-calculator', 'assets/uploads/constituent-units/faculty-of-commerce.webp', 'assets/uploads/constituent-units/faculty-of-commerce.webp', 'Faculty of Commerce offers B.Com. and M.Com. degrees focusing on corporate accounting, taxation, auditing, and financial analytics.', NULL, 'Dean & Principal', NULL, NULL, '0755-4700983, 7024144981', 'UGC', '2015', 'active'),
('69', 'Faculty of Computer Application', 'Computer Applications & IT', 'faculty-of-computer-application', 'fas fa-code', 'assets/uploads/constituent-units/faculty-of-computer-application.webp', 'assets/uploads/constituent-units/faculty-of-computer-application.webp', 'Faculty of Computer Application delivers DCA, PGDCA, and BCA degrees with hands-on coding in modern computing labs.', NULL, 'Dean & Principal', NULL, NULL, '0755-4700983, 7024144981', 'UGC', '2015', 'active'),
('70', 'Faculty of Library & Information Science', 'Allied Sciences', 'faculty-of-library-science', 'fas fa-book-reader', 'assets/uploads/constituent-units/faculty-of-library-science.webp', 'assets/uploads/constituent-units/faculty-of-library-science.webp', 'Faculty of Library & Information Science offers professional B.Lib. and M.Lib. degrees with modern digital archiving and metadata systems.', NULL, 'Dean & Principal', NULL, NULL, '0755-4700983, 7024144981', 'UGC', '2015', 'active'),
('71', 'Faculty of Yoga', 'Allied Sciences', 'faculty-of-yoga', 'fas fa-spa', 'assets/uploads/constituent-units/faculty-of-yoga.webp', 'assets/uploads/constituent-units/faculty-of-yoga.webp', 'Faculty of Yoga delivers holistic education through B.Sc. Yoga, M.Sc. Yoga, and PGDYT (Post Graduate Diploma in Yoga Therapy) programs.', NULL, 'Dean & Principal', NULL, NULL, '0755-4700983, 7024144981', 'UGC, Ayush', '2015', 'active'),
('72', 'Faculty of Fashion Technology & Design', 'Allied Sciences', 'faculty-of-fashion-technology-design', 'fas fa-tshirt', 'assets/uploads/constituent-units/faculty-of-fashion-technology-design.webp', 'assets/uploads/constituent-units/faculty-of-fashion-technology-design.webp', 'Faculty of Fashion Technology & Design delivers Diploma, B.Sc., and M.Sc. in Fashion Design with state-of-the-art apparel drafting, garment manufacturing, and textile studios.', NULL, 'Dean & Principal', NULL, NULL, '0755-4700983, 7024144981', 'UGC', '2016', 'active'),
('73', 'Faculty of Management', 'Allied Sciences', 'faculty-of-management', 'fas fa-graduation-cap', 'assets/uploads/faculty-management.jpg', NULL, 'Faculty of Management under Allied Sciences offers Bachelor of Business Administration (BBA) providing foundational and advanced education in business strategy, financial management, organizational behavior, and corporate leadership.', NULL, 'Dean & Principal', NULL, NULL, '0755-4700983, 7024144981', 'UGC', NULL, 'active'),
('74', 'Allied Sciences', 'Allied Sciences', 'allied-sciences', 'fas fa-graduation-cap', 'assets/uploads/constituent-units/allied-sciences.webp', 'assets/uploads/constituent-units/allied-sciences.webp', 'Allied Sciences encompasses multidisciplinary faculties delivering holistic higher education across Science, Humanities & Arts, Commerce, Management, Computer Applications, Library & Information Science, Yoga, and Fashion Technology.', NULL, 'Dean & Principal', NULL, NULL, '0755-4700983, 7024144981', 'UGC', NULL, 'active');
