INSERT INTO `blogs` (`id`, `title`, `slug`, `author`, `category`, `short_description`, `content`, `image_url`, `publish_date`, `views`, `status`, `created_at`, `updated_at`) VALUES
('1', 'Tarang 2026: Annual Inter-University Cultural & Sports Extravaganza', 'tarang-annual-fest-2026', 'Student Affairs Committee', 'Campus Life', 'A grand 3-day carnival bringing together over 5,000 students across central India for national-level music, dance, hackathons, and athletic tournaments.', '<p>Sarvepalli Radhakrishnan University (SRKU) celebrated its flagship annual inter-university cultural and athletic fest, <strong>Tarang 2026</strong>, with unprecedented zeal and grandeur on the lush green Bhopal campus. Spanning over three high-octane days, the mega event witnessed enthusiastic participation from more than 45 colleges and universities across India.</p><h3>Electrifying Events & Competitions</h3><p>The cultural fest featured a diverse array of competitive events covering fine arts, classical dance, battle of the bands, street plays (Nukkad Natak), fashion parade, and a 24-hour national hackathon organized by the Department of Computer Science & Engineering.</p><ul><li><strong>National Hackathon 2026:</strong> Over 120 tech teams developed AI-driven sustainable solutions for rural agriculture and healthcare robotics.</li><li><strong>Battle of Bands:</strong> High-voltage rock and classical fusion performances judged by national celebrity musicians.</li><li><strong>Sports Championships:</strong> Inter-collegiate tournaments in Cricket, Basketball, Football, Volleyball, and Badminton.</li></ul><p>The fest concluded with a mega celebrity concert, laser show, and an award distribution ceremony where outstanding student performers were awarded trophies and cash prizes worth ₹5 Lakhs.</p>', 'assets/uploads/2026/07/001.webp', '2026-08-15', '7', 'published', '2026-09-11 17:18:44', '2026-09-11 17:18:44'),
('2', 'International Conference on Emerging Horizons in AI, Machine Learning & Drug Discovery', 'international-conference-ai-drug-discovery', 'Faculty of Engineering & Pharmacy', 'Research & Tech', 'Renowned scientists, pharmacologists, and AI researchers from 12 countries convened at SRKU to explore computational biotechnology and automated healthcare diagnostics.', '<p>The Faculty of Engineering & Technology and Sri Sai College of Pharmacy at SRKU successfully hosted a two-day <strong>International Conference on Artificial Intelligence and Bio-Pharmaceutical Innovation (ICABPI 2026)</strong> in hybrid mode.</p><h3>Highlights of the Research Summit</h3><p>The conference brought together distinguished keynote speakers from premier global institutions, including IITs, AIIMS, and top pharmaceutical R&D labs from the USA, Germany, and Japan.</p><blockquote>\\\"The convergence of generative AI algorithms and molecular docking is drastically reducing drug discovery cycles from 10 years to mere months,\\\" remarked the keynote speaker during the inaugural address.</blockquote><p>Over 140 peer-reviewed research papers were presented by Ph.D. scholars, faculty members, and industrial researchers. All accepted manuscripts will be published in Scopus-indexed and UGC-CARE approved journals.</p>', 'assets/uploads/2026/07/002.webp', '2026-08-10', '1', 'published', '2026-09-11 17:18:44', '2026-09-11 17:18:44'),
('3', 'National Campus Placement Drive 2026: Record Offers & Highest Package of ₹12 LPA', 'national-campus-placement-drive-2026', 'Central Training & Placement Cell', 'Placements', 'Over 500 marquee recruiters including TCS, Wipro, Infosys, Sun Pharma, Cipla, and Tech Mahindra recruited graduating batches across technical and medical streams.', '<p>The Training and Placement Cell (T&P) at Sarvepalli Radhakrishnan University announced record-shattering outcomes for the 2026 graduating batch. With over 85 corporate recruiters visiting the campus in Phase-I alone, more than 820 job offers were extended to students across engineering, management, pharmacy, paramedical, and agriculture disciplines.</p><h3>Key Placement Highlights 2026</h3><ul><li><strong>Highest Package:</strong> ₹12.00 LPA secured by B.Tech CSE students in AI Product Engineering.</li><li><strong>Average Package:</strong> Significant 28% year-on-year jump reaching ₹5.20 LPA.</li><li><strong>Top Recruiting Partners:</strong> TCS, Infosys, Wipro, Cipla, Lupin, Sun Pharma, HCL Technologies, ICICI Bank, and Byju’s.</li></ul><p>SRKU’s dedicated corporate relations division provides rigorous pre-placement grooming including mock interviews, coding bootcamps, resume review clinics, and soft-skill development modules starting from the 3rd year.</p>', 'assets/uploads/2026/07/003.webp', '2026-08-05', '1', 'published', '2026-09-11 17:18:44', '2026-09-11 17:18:44'),
('4', 'Admissions Open 2026-27: Comprehensive Career Guide to 95+ Degree Programs', 'admissions-open-academic-session-2026-27', 'Office of Academic Admissions', 'Admissions', 'Explore premier academic pathways across Engineering, Medical, Dental, Ayurveda, Homoeopathy, Law, Nursing, Agriculture, and Management with merit scholarships.', '<p>Sarvepalli Radhakrishnan University (SRKU), Bhopal announces the commencement of online and campus admissions for the upcoming academic session <strong>2026-27</strong>. Applications are invited for over 95 multidisciplinary undergraduate, postgraduate, integrated, diploma, and doctoral (Ph.D.) programs.</p><h3>Why Choose SRK University?</h3><p>Recognized by UGC under Section 2(f) of the UGC Act 1956 and approved by statutory national councils (NMC, DCI, NCISM, NCH, AICTE, PCI, BCI, INC), the university offers modern experiential education backed by:</p><ul><li>750-Bed Teaching Multi-Specialty Hospital for live medical internships.</li><li>42+ State-of-the-Art Research Laboratories & High-Performance Computing Centers.</li><li>Merit Scholarships for meritorious students, sports champions, and reserved category candidates.</li><li>On-campus hostel accommodations, gymnasiums, sports arenas, and university-wide bus transportation.</li></ul><p>Interested candidates can apply online directly through the university website or visit the central counseling center at the Bhopal campus.</p>', 'assets/uploads/2026/07/004.webp', '2026-08-01', '0', 'published', '2026-09-11 17:18:44', '2026-09-11 17:18:44'),
('5', 'Modern Advancements in Ayurvedic & Integrative Medicine: SRKU Hospital Insights', 'advancements-ayurvedic-integrative-medicine', 'SRK College of Ayurveda Hospital', 'Medical & Health', 'How ancient Ayurvedic wisdom and modern clinical diagnostics combine to deliver holistic wellness and effective chronic disease management.', '<p>The Sarvepalli Radhakrishnan College of Ayurveda Hospital & Research Centre is leading the paradigm shift towards evidence-based integrative healthcare in Central India. Combining ancient Panchakarma therapies with state-of-the-art diagnostic imaging and pathology labs, the 100-bed Ayurvedic hospital treats over 200 patients daily.</p><h3>Specialized Treatment Wings</h3><ul><li><strong>Kayachikitsa (Internal Medicine):</strong> Holistic management of metabolic, joint, and chronic lifestyle disorders.</li><li><strong>Panchakarma Center:</strong> Specialized detoxification treatments including Vamana, Virechana, Basti, Nasya, and Raktamokshana.</li><li><strong>Shalya Tantra:</strong> Advanced Kshara Sutra therapy for anorectal ailments with zero recurrence.</li></ul><p>Students of BAMS and MD Ayurveda receive direct hands-on clinical rotations under senior Ayurvedic doctors and clinical researchers.</p>', 'assets/uploads/2026/07/001.webp', '2026-07-25', '0', 'published', '2026-09-11 17:18:44', '2026-09-11 17:18:44'),
('6', 'Sustainable Smart Agriculture & Drone Technology in Precision Farming', 'sustainable-smart-agriculture-drone-technology', 'Faculty of Agriculture', 'Agriculture & Bio', 'SRKU Faculty of Agriculture integrates IoT soil sensors, automated drip irrigation, and aerial drone surveillance across its 50-acre experiential farm.', '<p>The Faculty of Agriculture at SRKU is transforming traditional agricultural education into high-tech sustainable agri-business. With 50+ acres of dedicated experimental farms, polyhouses, and vermicompost units, students gain firsthand experience in organic cultivation, seed technology, and drone-assisted crop monitoring.</p><h3>Key Training Verticals</h3><ul><li><strong>Precision Spraying:</strong> Agricultural drones for micro-nutrient spraying and pest infestation scanning.</li><li><strong>Hydroponics & Greenhouses:</strong> Soil-less vegetable cultivation and climate-controlled floriculture.</li><li><strong>Soil Health Laboratories:</strong> Rapid testing of NPK ratios and organic carbon levels for local farmers.</li></ul><p>Graduates from B.Sc. (Hons) Agriculture secure prestigious roles in NABARD, IFFCO, agrochemical multinationals, and state agricultural departments.</p>', 'assets/uploads/2026/07/002.webp', '2026-07-18', '3', 'published', '2026-09-11 17:18:44', '2026-09-11 17:18:44');
INSERT INTO `news` (`id`, `title`, `slug`, `content`, `category`, `publish_date`, `image_url`, `is_ticker`, `created_at`) VALUES
('1', 'Admissions Open for Academic Session 2026-27', 'admissions-open-2026', 'Applications are invited for UG, PG, Diploma, and Ph.D. programs across Engineering, Pharmacy, Nursing, Management, Agriculture, Law, and Medicine.', 'Admission', '2026-08-01', 'assets/images/news1.jpg', '1', '2026-09-11 17:18:44'),
('2', 'National Campus Placement Drive 2026 - Highest Package 12 LPA', 'placement-drive-2026', 'Top tier recruiters including TCS, Wipro, Infosys, Cipla, and Sun Pharma participated in the annual mega placement drive.', 'Placement', '2026-08-05', 'assets/images/news2.jpg', '1', '2026-09-11 17:18:44'),
('3', 'International Conference on Advanced Research in Pharmaceuticals & AI', 'intl-conference-2026', 'SRKU hosted delegates from 12 countries to discuss AI in drug discovery and sustainable energy.', 'Event', '2026-08-10', 'assets/images/news3.jpg', '0', '2026-09-11 17:18:44'),
('4', 'Tarang 2026 - Annual Inter-University Sports & Cultural Fest Announced', 'tarang-annual-fest-2026', 'Three days of vibrant cultural performances, sports tournaments, and tech competitions.', 'Campus Life', '2026-08-15', 'assets/images/news4.jpg', '0', '2026-09-11 17:18:44');
