INSERT INTO `board_members` (`id`, `name`, `designation`, `category`, `role`, `representation`, `bio`, `icon`, `photo`, `sort_order`, `status`, `created_at`) VALUES
('8', 'Dr. Sunil Kapoor', 'Chairman & Chief Patron', 'leadership', 'Member', 'Founder & Visionary, RKDF Education Society', 'Guiding the RKDF group and SRK University since 1995 with an inspiring mission of affordable, benchmarked multidisciplinary higher education.', 'fa-crown', 'assets/uploads/2026/08/dr-sunil-kapoor.jpeg', '1', 'active', '2026-09-16 11:48:02'),
('9', 'Mrs. Janak Kapoor', 'Chancellor', 'leadership', 'Member', 'Statutory Head of the University', 'Presiding officer of university convocations and apex custodian of university ethos and statutory adherence.', 'fa-user-tie', 'assets/uploads/2026/08/chancellor.jpeg', '2', 'active', '2026-09-16 11:48:02'),
('10', 'Dr. Priyanka Jaiswal', 'Vice Chancellor', 'leadership', 'Member', 'Principal Academic & Executive Officer', 'Leading the university\'s NEP 2020 pedagogical transformation, multidisciplinary research, and international accreditations.', 'fa-graduation-cap', '', '3', 'active', '2026-09-16 11:48:02'),
('11', 'Shri. Ratnesh Jain', 'Member', 'sponsoring', 'Member', 'Sponsoring Body Representative', 'Distinguished member nominated by RKDF Education Society contributing to institutional resource planning and development.', 'fa-briefcase', '', '4', 'active', '2026-09-16 11:48:02'),
('12', 'Dr. Amarjeet Singh', 'Member', 'sponsoring', 'Member', 'Sponsoring Body Representative', 'Senior educationist and policy strategist supporting institutional expansion and regulatory compliance.', 'fa-user-check', '', '5', 'active', '2026-09-16 11:48:02'),
('13', 'Dr. Aparna Paliwal', 'Member', 'academic', 'Member', 'Eminent Academician', 'Senior professor advising the university on outcome-based education, curriculum restructuring, and pedagogical innovations.', 'fa-book-reader', '', '6', 'active', '2026-09-16 11:48:02'),
('14', 'Dr. Vikram Singh', 'Member', 'academic', 'Member', 'Academic & Research Expert', 'Guiding scientific research publications, doctoral review committees, and inter-institutional research collaborations.', 'fa-microscope', '', '7', 'active', '2026-09-16 11:48:02'),
('15', 'Mr. Santosh Negi', 'Member', 'administration', 'Member', 'Industry & Administrative Expert', 'Providing strategic direction for corporate relations, campus placements, and industrial internships.', 'fa-chart-line', '', '8', 'active', '2026-09-16 11:48:02'),
('16', 'Dr. Neha Dubey', 'Member', 'academic', 'Member', 'Faculty Representative', 'Representing faculty governance, faculty development programs, and interdisciplinary student initiatives.', 'fa-chalkboard-teacher', '', '9', 'active', '2026-09-16 11:48:02'),
('17', 'Dr. S.S. Pawar', 'Member Secretary & Registrar', 'administration', 'Member', 'Executive Head of Administration', 'Custodian of university records, legal affairs, statutory councils, and university secretariat.', 'fa-id-card', '', '10', 'active', '2026-09-16 11:48:02');
