INSERT INTO `facilities` (`id`, `title`, `icon`, `image`, `description`, `sort_order`, `status`, `created_at`) VALUES
('1', '42+ Research Laboratories', 'fa-microscope', 'assets/uploads/2026/07/lab-and-research.webp', 'Equipped with high-performance computing clusters, robotics simulation kits, automated HPLC drug testing systems, and agronomy research suites.', '1', 'active', '2026-09-16 11:48:02'),
('2', 'Central Digital Library', 'fa-book-reader', 'assets/uploads/2026/07/library.webp', 'Over 50,000+ volumes, IEEE, Scopus, Springer e-journal subscriptions, DELNET network access, and quiet digital reading rooms.', '2', 'active', '2026-09-16 11:48:02'),
('3', 'Smart AC Auditoriums', 'fa-chalkboard-teacher', 'assets/uploads/2026/07/Operation-Theatre.webp', 'Fully air-conditioned multi-tiered amphitheaters with Dolby surround sound, interactive smartboards, and live video conferencing.', '3', 'active', '2026-09-16 11:48:02'),
('4', 'Sports Complex & Gym', 'fa-running', 'assets/uploads/2026/07/sports.webp', 'Full-size cricket turf ground, floodlit basketball courts, volleyball, indoor badminton arena, and modern fitness gymnasium.', '4', 'active', '2026-09-16 11:48:02'),
('5', 'On-Campus Hostels', 'fa-bed', 'assets/uploads/2026/07/hostel.webp', 'Separate boys and girls residential blocks with Wi-Fi, 24x7 security surveillance, water purifiers, and hygienic multi-cuisine mess.', '5', 'active', '2026-09-16 11:48:02'),
('6', '750+ Bed Teaching Hospital', 'fa-hospital-alt', 'assets/uploads/2026/07/INFRA-STRUCTURE-SRKU-05.webp', 'Full-fledged super-specialty hospital with 24x7 ICU, emergency casualty, operation theaters, and clinical diagnostic pathology.', '6', 'active', '2026-09-16 11:48:02');
